import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Game auto-update: the remote script, its output parser, and the verdict.
 *
 * INCIDENT ("Game auto-update cannot fail", honest inventory #3): the old
 * `updateCommand` returned
 *
 *     set -e; <steam>; <restart>; true
 *
 * where the steamcmd call ended `|| true` and was skipped entirely when steamcmd
 * was absent, every restart branch ended `|| true`, and the whole command ended
 * `; true`. The remote command could NOT exit non-zero. So `gameUpdate` always
 * reached its notification and always told the customer *"The latest server
 * update was applied and the service was restarted."* — for a box where steamcmd
 * was not installed, where no matching systemd unit existed, or where the service
 * came back dead. This runs unattended every 6 hours.
 *
 * `worker/apps.ts` is the model this follows: every operation declares what it
 * PROVES, the remote side emits explicit markers, and an exit code of 0 is never
 * accepted as evidence. (`wp_die()` prints its error and exits 0 — that is the
 * lesson, and `|| true` is the same lesson wearing a different hat.)
 *
 * A second honesty problem is fixed here too: minecraft and terraria have no
 * steamcmd app id, so for those families the job never updated ANYTHING — it
 * restarted a service. The success message now says which of the two happened.
 *
 * Pure and dependency-free: no SSH, no clock. Covered by test/game-update.test.ts,
 * which also runs `sh -n` and `dash -n` over the generated script.
 */

/**
 * Steam dedicated-server app IDs for families whose game files are updated by
 * steamcmd running DIRECTLY ON THE HOST, next to a systemd unit that manages the
 * server process itself (not a container).
 *
 * valheim/rust/palworld/cs2 were REMOVED from this table 2026-09-10, found live
 * via a real customer's Valheim server (`terraheim`) failing its GAME_UPDATE job
 * on every single run for 2 days straight with "steamcmd is not installed" —
 * true, but not fixable, because all four are actually Docker-run
 * (`OsTemplate.setupScript` installs Docker and `docker run`s an image; a thin
 * systemd unit wraps it as `ExecStart=docker start -a <name>` purely so the rest
 * of the platform can treat it like any other service). steamcmd for these lives
 * inside the container's own image, if it exists at all — never on the host —
 * so `command -v steamcmd` on the host can never succeed, and the job was
 * pointlessly retrying and re-notifying the customer every ~6h/24h forever for
 * 5 real live servers (3 valheim, 1 rust, 1 palworld) with zero chance of ever
 * resolving. This is the exact bug class already fixed for waves 3/4/8/9 and
 * the Plutonium family below — those all correctly stayed OUT of this table
 * from the start; these four just predate that convention and were never
 * migrated onto it until now. Restart-only (via the wrapper unit, confirmed
 * live to correctly call `docker start -a`/`docker stop`) is what these get
 * instead — see `updatesFromSteam()`.
 */
export const STEAM_APPID: Partial<Record<GameFamily, string>> = {};

/** systemd service name candidates per family (first that exists wins). */
export const SERVICE_HINT: Record<GameFamily, string> = {
  minecraft: "minecraft",
  valheim: "valheim",
  rust: "rust",
  palworld: "palworld",
  cs2: "cs2",
  terraria: "terraria",
  ark: "ark",
  satisfactory: "satisfactory",
  projectzomboid: "projectzomboid",
  sdtd: "sdtd",
  vrising: "vrising",
  enshrouded: "enshrouded",
  factorio: "factorio",
  gmod: "gmod",
  conan: "conan",
  unturned: "unturned",
  theforest: "theforest",
  sonsoftheforest: "sonsoftheforest",
  bedrock: "bedrock",
  // ── Wave 3 SCAFFOLD (2026-08-31). Kept OUT of STEAM_APPID on purpose: without a
  //    Steam app id these families are "restart-only" for the auto-update job (never
  //    claim a steam update they didn't run). Their verified dedicated-server app ids
  //    are recorded in the review plan and get wired in alongside the real setup
  //    scripts, not here. ──
  schedule1: "schedule1",
  dragonwilds: "dragonwilds",
  sunkenland: "sunkenland",
  abioticfactor: "abioticfactor",
  corekeeper: "corekeeper",
  icarus: "icarus",
  // ── Wave 4 (2026-08-31). Same rule as Wave 3 above: all seven are Docker-run
  //    (prisma/seed-wave4-games.ts), so even the ones with a real, verified Steam
  //    dedicated-server app id (arkasa/soulmask/dst/necesse/tf2/l4d2) are kept OUT
  //    of STEAM_APPID here — this job's steamcmd branch assumes steamcmd installed
  //    directly on the host next to a systemd unit, which none of these have; the
  //    update actually happens inside the container's own image on
  //    restart/redeploy. Restart-only, same as every other Dockerized family. ──
  arkasa: "arkasa",
  soulmask: "soulmask",
  dst: "dst",
  vintagestory: "vintagestory",
  necesse: "necesse",
  tf2: "tf2",
  l4d2: "l4d2",
  // ── Wave 8 (2026-08-31). Same rule as Waves 3/4: all six are Docker-run
  //    (prisma/seed-wave8-games.ts), so kept OUT of STEAM_APPID — the update
  //    actually happens inside the container's own image on restart/redeploy.
  //    Restart-only, same as every other Dockerized family. ──
  nightingale: "nightingale",
  squad: "squad",
  spaceengineers: "spaceengineers",
  kf2: "kf2",
  barotrauma: "barotrauma",
  sandstorm: "sandstorm",
  // ── Wave 9 (2026-08-31). Same rule as Waves 3/4/8: all five are Docker-run
  //    (prisma/seed-wave9-games.ts), so kept OUT of STEAM_APPID — the update
  //    actually happens inside the container's own image on restart/redeploy.
  //    Restart-only, same as every other Dockerized family. ──
  mordhau: "mordhau",
  theisle: "theisle",
  stationeers: "stationeers",
  eco: "eco",
  empyrion: "empyrion",
  plutoniumt4: "plutoniumt4",
  // T5/T6/IW5 (2026-08-31): same rule as plutoniumt4 above — all Docker-run
  // via the Plutainer image (prisma/seed-plutonium.ts), so kept OUT of
  // STEAM_APPID and restart-only here too.
  plutoniumt5: "plutoniumt5",
  plutoniumt6: "plutoniumt6",
  plutoniumiw5: "plutoniumiw5",
  armareforger: "armareforger",
  cs16: "cs16",
  // ets2/ats (Wave 11): same rationale as the Plutonium families above —
  // community Docker image (LsHallo/ets2-dedicated-convoy-server), kept out
  // of STEAM_APPID and restart-only here. The image's own entrypoint.sh
  // handles the SCS SteamCMD update itself on every container start
  // (ETS_SERVER_UPDATE_ON_START, default true) — nothing this platform needs
  // to separately trigger.
  ets2: "ets2",
  ats: "ats",
  // dayz (Wave 11, 2026-09-24): same "restart-only" shape as every other
  // family above — STEAM_APPID is empty for the whole catalog today, so this
  // is consistent with the rest of the file, not a DayZ-specific gap.
  dayz: "dayz",
};

/** Does this family have an update source at all, or is the job only a restart? */
export function updatesFromSteam(family: GameFamily): boolean {
  return Boolean(STEAM_APPID[family]);
}

/** Seconds we wait for the unit to come back before we stop claiming anything. */
export const RESTART_WAIT_TRIES = 30;
export const RESTART_WAIT_SLEEP_S = 2;

/**
 * Should `gameUpdateSweep` even enqueue a check for this candidate?
 *
 * `Server.status` is the VM's own power state, not the game service inside
 * it — `gamePower`'s own doc comment (worker/game-control.ts) is explicit
 * that the two are "genuinely different things". So a customer who presses
 * Stop on the dashboard (GAME_POWER "stop") leaves `status` at RUNNING
 * forever, and the sweep — which only ever looks at `status`+`autoUpdate` —
 * kept enqueueing a GAME_UPDATE job against it every cycle with no way to
 * know the service was off on purpose. Every one of those jobs then failed
 * with "your game server is NOT running", which is TRUE and also not news:
 * the customer did that themselves.
 *
 * Found live 2026-09-17: suplosmp (bedrock) generated a FAILED GAME_UPDATE
 * job on every single sweep for 28+ straight hours after its owner pressed
 * Stop and hadn't turned it back on — the same "customer would learn to
 * ignore it" erosion `notifyFailureOnce` already exists to prevent for
 * notifications, just unaddressed on the job-creation side.
 *
 * `gamePower` persists the post-action `systemctl is-active` result to
 * `Server.gameConfig._serviceState` (its own doc comment explains why: the
 * dashboard's status dot needed it). That is the one signal that distinguishes
 * "the customer turned this off" from "this crashed" — a crash is never
 * written here, only an explicit start/stop/restart action is. So only the
 * exact value "inactive" (a clean, completed stop) skips the sweep; anything
 * else — "failed" (a crash), "activating" (mid-restart), missing/stale — is
 * still checked normally, because those are precisely what this job exists
 * to catch.
 */
export function eligibleForUpdateSweep(gameConfig: unknown): boolean {
  const state = (gameConfig as Record<string, unknown> | null | undefined)?.["_serviceState"];
  return state !== "inactive";
}

/**
 * Build the remote script.
 *
 * Design rules, each of which the old one-liner broke:
 *
 *  - No `set -e` and no trailing `; true`. Control flow is explicit, and the exit
 *    status is irrelevant — the MARKERS are the contract, so a truncated or
 *    dropped connection is detectable (no `NXGU:END`) rather than indistinguishable
 *    from success.
 *  - steamcmd's own exit code is not trusted (it is famously unreliable and
 *    frequently non-zero on a perfectly good update). We match its own success
 *    line instead, and report the code alongside.
 *  - "no unit matched" is an outcome we emit, not a branch we swallow.
 *  - The post-restart state is polled and reported verbatim. `active` is the only
 *    thing that will be called success upstream.
 *
 * `family` is constrained to GAME_FAMILIES by the caller AND re-checked here, so
 * nothing unvalidated is interpolated into the shell.
 */
export function updateCommand(family: GameFamily): string {
  if (!GAME_FAMILIES.includes(family)) throw new Error(`not a game family: ${family}`);
  const appId = STEAM_APPID[family];
  const svc = SERVICE_HINT[family];
  // Both are compile-time constants from the tables above — never customer input.

  // Emitted by every branch that must not go on to restart the service.
  const stopHere = [
    `st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `say "SKIPPED_RESTART:1"`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
    `exit 0`,
  ];

  const steam = appId
    ? [
        `fresh=0`,
        `if command -v steamcmd >/dev/null 2>&1; then`,
        `  out=$(steamcmd +login anonymous +app_update ${appId} validate +quit 2>&1); rc=$?`,
        `  say "STEAM_RC:$rc"`,
        // steamcmd prints "Success! App '<id>' already up to date." when there was
        // nothing to download, and "Success! App '<id>' fully installed." when
        // there was. Both used to match one grep, so the two outcomes were
        // indistinguishable — see the CURRENT/OK split in the header note.
        `  if printf '%s' "$out" | grep -q "Success! App '${appId}' already up to date"; then`,
        `    say "STEAM:CURRENT"`,
        `  elif printf '%s' "$out" | grep -q "Success! App '${appId}'"; then`,
        `    fresh=1; say "STEAM:OK"`,
        `  else`,
        `    say "STEAM:FAIL"`,
        `    printf '%s' "$out" | grep -i 'error' | head -3 | while IFS= read -r l; do say "STEAM_ERR:$l"; done`,
        `  fi`,
        `else`,
        `  say "STEAM:ABSENT"`,
        `fi`,
        // Do NOT bounce a healthy game server for an update that did not happen:
        // a restart kicks every connected player off for nothing, and it would
        // make "the service was restarted" the only true half of a false claim.
        // This now also covers the "already up to date" case, which is the COMMON
        // one — it ran every 6 hours and disconnected everybody four times a day.
        `if [ "$fresh" != "1" ]; then`,
        ...stopHere.map((l) => `  ${l}`),
        `fi`,
      ].join("\n")
    : [
        // No update source exists for this family, so there is nothing a restart
        // could apply. Restarting anyway is a pure loss: every connected player
        // is disconnected, four times a day, forever, to change nothing. The
        // rule two paragraphs up applies here MOST, and used not to be applied
        // here at all.
        `say "STEAM:NA"`,
        ...stopHere,
      ].join("\n");

  return [
    `say() { printf 'NXGU:%s\\n' "$1"; }`,
    // 1. Resolve the unit. `systemctl cat` succeeds only for a unit that exists.
    `unit=""`,
    `for c in ${svc} ${svc}-server; do`,
    `  if systemctl cat "$c" >/dev/null 2>&1; then unit="$c"; break; fi`,
    `done`,
    `if [ -z "$unit" ]; then`,
    `  unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}')`,
    `fi`,
    `if [ -z "$unit" ]; then say "UNIT:NONE"; say "END"; exit 0; fi`,
    `say "UNIT:$unit"`,
    `was=$(systemctl is-active "$unit" 2>/dev/null); say "WAS:${"$"}{was:-unknown}"`,
    // 2. Update the game files, where such a thing exists.
    steam,
    // 3. Restart, and report the real result of the restart call.
    `systemctl restart "$unit" >/dev/null 2>&1; say "RESTART_RC:$?"`,
    // 4. Wait for it to settle. A game server can take a while to open its port,
    //    so "activating" is a distinct answer from "failed" and both are reported.
    `i=0; st=""`,
    `while [ $i -lt ${RESTART_WAIT_TRIES} ]; do`,
    `  st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `  if [ "$st" = "active" ] || [ "$st" = "failed" ]; then break; fi`,
    `  i=$((i+1)); sleep ${RESTART_WAIT_SLEEP_S}`,
    `done`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

export type GameUpdateFacts = {
  /** The systemd unit the script acted on, or null when nothing matched. */
  unit: string | null;
  /** `systemctl is-active` before the restart. */
  wasActive: string;
  /** Exit code of `systemctl restart`, or null when it never ran. */
  restartRc: number | null;
  /** `systemctl is-active` after the restart, settled or timed out. */
  state: string;
  /**
   * "ok" = steamcmd downloaded a NEW build. "current" = it confirmed the server
   * was already up to date and downloaded nothing. Collapsing those two into one
   * value is what made "<game> updated on <host>" fire every 6 hours forever.
   */
  steam: "ok" | "current" | "failed" | "absent" | "na" | "unknown";
  steamRc: number | null;
  steamErrors: string[];
  /** Did the script run to completion? No END marker means we know nothing. */
  complete: boolean;
};

export function parseGameUpdateOutput(out: string): GameUpdateFacts {
  const text = String(out ?? "");
  const one = (re: RegExp): string | null => re.exec(text)?.[1] ?? null;

  const steamRaw = one(/^NXGU:STEAM:(\w+)$/m);
  const steam =
    steamRaw === "OK" ? "ok"
    : steamRaw === "CURRENT" ? "current"
    : steamRaw === "FAIL" ? "failed"
    : steamRaw === "ABSENT" ? "absent"
    : steamRaw === "NA" ? "na"
    : "unknown";

  const rc = (re: RegExp): number | null => {
    const v = one(re);
    return v === null ? null : Number(v);
  };

  const unitLine = one(/^NXGU:UNIT:(.+)$/m);
  const steamErrors: string[] = [];
  for (const m of text.matchAll(/^NXGU:STEAM_ERR:(.*)$/gm)) steamErrors.push(m[1].trim());

  return {
    unit: unitLine === null || unitLine === "NONE" ? null : unitLine.trim(),
    wasActive: one(/^NXGU:WAS:(.*)$/m)?.trim() || "unknown",
    restartRc: rc(/^NXGU:RESTART_RC:(-?\d+)$/m),
    state: one(/^NXGU:STATE:(.*)$/m)?.trim() || "unknown",
    steam,
    steamRc: rc(/^NXGU:STEAM_RC:(-?\d+)$/m),
    steamErrors,
    complete: /^NXGU:END$/m.test(text),
  };
}

// ---------------------------------------------------------------------------
// The verdict
// ---------------------------------------------------------------------------

export type GameUpdateVerdict =
  | {
      ok: true;
      title: string;
      body: string;
      /**
       * Is this an EVENT worth interrupting the customer for?
       *
       * This runs unattended every 6 hours. `notifyFailureOnce` already exists
       * because "the customer would learn to ignore them — which is the same
       * outcome as not telling them"; the success path had no equivalent and
       * notified on every single pass, so a healthy server produced four
       * notifications a day, forever, all of them titled "<game> updated on
       * <host>" when nothing had been updated. Only a real, observed change is
       * an event.
       */
      notify: boolean;
    }
  | { ok: false; reason: string };

/**
 * Turn observed facts into the one thing the customer is told.
 *
 * Every refusal names the reason AND the command to run, because "update failed"
 * on a game server six hours after the fact is useless without a next step.
 * Every success states precisely what was proven — including, for minecraft and
 * terraria, that no game update took place at all, because there is no update
 * source for those families and saying otherwise was the original lie.
 */
export function judgeGameUpdate(opts: {
  family: GameFamily;
  hostname: string;
  facts: GameUpdateFacts;
}): GameUpdateVerdict {
  const { family, hostname, facts: f } = opts;
  const appId = STEAM_APPID[family];

  if (!f.complete) {
    return {
      ok: false,
      reason:
        `the update script did not run to completion on ${hostname} (no end marker), so nothing about ` +
        `this run can be verified — the connection may have dropped or the command timed out. ` +
        `Nothing is being claimed. Re-run it by hand: systemctl status <your ${family} unit>`,
    };
  }

  if (!f.unit) {
    return {
      ok: false,
      reason:
        `no systemd service for ${family} was found on ${hostname}, so nothing was updated and ` +
        `nothing was restarted. Check what the server actually runs with: ` +
        `systemctl list-units --type=service | grep -i ${family}`,
    };
  }

  if (appId && f.steam === "absent") {
    return {
      ok: false,
      reason:
        `steamcmd is not installed on ${hostname}, so the ${family} game files were NOT updated. ` +
        `Auto-update cannot work on this server until it is present: apt-get install -y steamcmd ` +
        `(or reinstall from the ${family} image).`,
    };
  }

  if (appId && f.steam !== "ok" && f.steam !== "current") {
    const detail = f.steamErrors.length ? ` steamcmd said: ${f.steamErrors.slice(0, 3).join(" | ")}` : "";
    return {
      ok: false,
      reason:
        `steamcmd did not report a successful update of app ${appId} on ${hostname} ` +
        `(exit ${f.steamRc ?? "unknown"}), so the game files were not updated and the service was ` +
        `left alone.${detail} Re-run by hand: steamcmd +login anonymous +app_update ${appId} validate +quit`,
    };
  }

  // Nothing was restarted on these paths, so the state we observed is simply the
  // state the server was already in — do not describe it as a restart outcome.
  const restarted = f.steam === "ok";

  if (f.state !== "active") {
    return {
      ok: false,
      reason: restarted
        ? `${f.unit} on ${hostname} is "${f.state}" after the restart` +
          (f.restartRc !== null && f.restartRc !== 0 ? ` (systemctl restart exited ${f.restartRc})` : "") +
          `, so your game server is NOT running. It was "${f.wasActive}" before this ran. ` +
          `Diagnose with: systemctl status ${f.unit} ; journalctl -u ${f.unit} -n 50`
        : `${f.unit} on ${hostname} is "${f.state}" — your game server is NOT running. Nothing was ` +
          `updated or restarted by this check, so this is not something we just did to it. ` +
          `Diagnose with: systemctl status ${f.unit} ; journalctl -u ${f.unit} -n 50`,
    };
  }

  if (f.steam === "ok") {
    return {
      ok: true,
      notify: true, // a new build really was downloaded and applied
      title: `${family} updated on ${hostname}`,
      body:
        `steamcmd downloaded a new build of app ${appId}, and ${f.unit} was restarted and is active again ` +
        `(verified with systemctl, not assumed from an exit code).`,
    };
  }

  if (f.steam === "current") {
    return {
      ok: true,
      notify: false, // nothing happened; four of these a day is noise, not news
      title: `${family} on ${hostname} is already up to date`,
      body:
        `steamcmd confirmed app ${appId} is already up to date, so nothing was downloaded and ${f.unit} was ` +
        `NOT restarted — no players were disconnected. It is active.`,
    };
  }

  // No update source exists for this family. Say that, rather than implying one —
  // and do not restart, which is all this job could otherwise do here.
  return {
    ok: true,
    notify: false,
    title: `${family} server checked on ${hostname}`,
    body:
      `${f.unit} is active (verified). ${family} has no automatic update source on Nxeon, so there was ` +
      `nothing to download and your server was NOT restarted — restarting it every few hours would ` +
      `disconnect your players to change nothing. Update the server files yourself when a new version ships.`,
  };
}

  // PROVISION uses (worker/provision-health.ts's checkGamePortOpen +
  // gamePortBoundInGuest), reused here for the other place this class of bug
  // hid: a systemd unit reporting "active" proves the OBJECT exists, never
  // that the game process inside actually bound its port. Best-effort and
  // deliberately short (GAME_POWER_PORT_CHECK_TIMEOUT_MS) — families with no
  // GAME_PORT entry, or a NAT server whose game port isn't forwarded, skip
  // this silently rather than block or falsely fail on a check that can't
  // mean anything for them.
  if (action !== "stop" && state === "active") {
    const game = gamePortForServer(server);
    const checkHost = server.dedicatedIp?.address ?? server.node?.publicIp ?? null;
    if (game && checkHost) {
      const portCheck = await checkGamePortOpen(checkHost, game.port, game.protocol, {
        timeoutMs: spec.powerStartTimeoutMs ?? GAME_POWER_PORT_CHECK_TIMEOUT_MS,
        intervalMs: GAME_POWER_PORT_CHECK_INTERVAL_MS,
        verifyBound: () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol),
      });
      if (!portCheck.ok) {
        await notify(
          server.userId,
          `${spec.label} service ${action}ed, but the game never came online`,
          `systemd reports ${server.hostname} as active, but nothing is actually answering on ` +
            `${game.port}/${game.protocol}: ${portCheck.error ?? "no further detail"}. Check the game's own logs — ` +
            `this usually means the server process itself failed to start even though its service is "running".`,
          href
        );
        throw new Error(`game power: ${action} reported active but port ${game.port}/${game.protocol} never bound: ${portCheck.error ?? ""}`);
      }
    }
  }

  await notify(
    server.userId,
    `${spec.label} service ${action}ed on ${server.hostname}`,
    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
    href
  );

  // Persist the real systemd state so the dashboard's status dot can reflect
  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
  // `Server.status` (the VM's own power state) — those are genuinely
  // different things, but the panel's "Online/Offline" label was reading
  // `Server.status` alone, so a customer who stopped just their game service
  // (VM still up) kept seeing "Online" no matter what they did. Found live
  // 2026-09-09 via a real customer confused why "Status: Online" never
  // changed after repeated stop/start attempts. `_serviceState` follows the
  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
  // `_appliedAt` elsewhere in this file's siblings — no schema migration
  // needed for what's fundamentally transient, best-effort runtime state.
  try {
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
  } catch (e) {
    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
  }
}

/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
export async function gameBackup(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game backup: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");

  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
    const dir = await remoteLocateDir(conn, spec.dataRoots);
    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
    // from the located (allowlisted) dir; every value interpolated is single-quoted.
    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
    const parent = dir.replace(/\/[^/]+$/, "") || "/";
    const base = dir.replace(/^.*\//, "");
    const script =
      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
      `stat -c '%s' ${shq(archive)}`;
    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
  });

  if (!outcome.ok) {
    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
    throw new Error(`game backup failed: ${outcome.msg}`);
  }
  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
  await notify(
    server.userId,
    `${spec.label} world backup ready on ${server.hostname}`,
    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
    href
  );
}

const REINSTALL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true, sshManagementKeyEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true } },
  osTemplate: { select: { family: true, setupScript: true } },
  gamePlan: { select: { gameFamily: true } },
  gameVariant: true,
  gameConfig: true,
} as const;

type ReinstallServer = ControlServer & {
  osTemplate: { family: string | null; setupScript: string | null };
  gameVariant: string | null;
  gameConfig: unknown;
};

/**
 * How long GAME_REINSTALL's post-action port check waits before giving up.
 * Longer than GAME_POWER's (a fresh `docker create` can need to pull an image,
 * not just restart an already-cached container) but still far short of
 * provisioning's own 300s — a wipe+reinstall that's still not up after a
 * minute gets a "check back shortly" notification rather than a hard failure
 * (the SSH script itself already confirmed the systemd unit is active; this
 * is only extra confirmation the game process itself bound its port).
 */
const GAME_REINSTALL_PORT_CHECK_TIMEOUT_MS = 60_000;
const GAME_REINSTALL_PORT_CHECK_INTERVAL_MS = 4_000;

/**
 * GAME_REINSTALL — Danger Zone "Wipe & reinstall this game". Re-provisions the
 * GAME ONLY against the SAME, already-existing VM:
 *
 *   1. stop the game's systemd unit and `docker rm -f` its container
 *   2. wipe the CONTENTS of the game's own bind-mounted data directory(ies) —
 *      parsed straight from the family's real setupScript `-v host:container`
 *      flags (`dockerHostMountsFrom`, worker/game-variant.ts) — never a
 *      guessed path, same provenance discipline as lib/games.ts's
 *      GAME_JOIN_PORT_OVERRIDE/GAME_EXTRA_JOIN_PORTS
 *   3. re-run a FRESH build of the setup script (`buildGameSetupScript`),
 *      which reapplies the customer's CURRENT gameVariant/gameConfig — so a
 *      setting that silently never applied (see docs/DOCUMENTATION.md — only
 *      5 of 42 families apply saved settings today) gets a real chance to
 *      take effect on the fresh install — and mints brand-new per-server
 *      secrets for palworld/rust/cs2, the same "rotate, don't keep the old
 *      ones" rule `reinstall()`'s own comment (worker/index.ts) applies to
 *      the VPS root password.
 *
 * Never touches the VPS/VM itself: no Proxmox call, no vmid change, no
 * destroy/reclone, no IP/SSH-host-key change — this is exactly what the
 * Danger Zone subtitle promises ("Reinstall, wipe or cancel") that nothing
 * previously implemented. The VM must already be RUNNING (this runs entirely
 * over SSH into the live guest; unlike the VPS-level REINSTALL, there is no
 * Proxmox path that works on a stopped VM).
 *
 * Full "change game" (swap to a different family) is NOT implemented here —
 * that needs a different OsTemplate/GamePlan, different ports (see
 * lib/games.ts), possibly a different RCON setup, and a real disk-footprint
 * check, which is real, separable infrastructure work. Shipping wipe+
 * reinstall-SAME-game now rather than a half-built family-swap is the
 * deliberate scope line the task that produced this drew; the dashboard copy
 * must say "Reinstall (same game)" and note full game-swap as a documented
 * follow-up, not silently imply it does more than it does.
 */
export async function gameReinstall(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game reinstall: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: REINSTALL_FIELDS })) as ReinstallServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `${spec.label} reinstalled (sandbox) on ${server.hostname}`,
      "Sandbox only — no VM was contacted; nothing was actually wiped or reinstalled.",
      href
    );
    return;
  }
  // Runs entirely over SSH into the live guest — there is no Proxmox path here
  // the way the VPS-level REINSTALL has, so (unlike that one) a stopped VM
  // cannot be reinstalled from here; the customer must start the VPS first.
  if (server.status !== "RUNNING") throw new Error("game reinstall: the VPS must be running to reinstall the game");

  const gameSetup = buildGameSetupScript(server);
  if (!gameSetup) throw new Error("game reinstall: no setup script is on file for this template");

  const raw = server.osTemplate.setupScript ?? "";
  const containerName = dockerContainerNameFrom(raw);
  const hostDirs = dockerHostMountsFrom(raw);
  if (!containerName || hostDirs.length === 0) {
    // Fail safe rather than silently skip the wipe — every real family's
    // setupScript matches this shape today (see prisma/seed-wave*.ts), so this
    // should never trigger; it exists for a future family whose script has a
    // genuinely different shape, which must not fall through to "reinstall
    // without wiping" unnoticed.
    throw new Error("game reinstall: could not determine this server's container name or data directory from its setup script — refusing to wipe blind");
  }
  const unitName = spec.serviceHints[0];

  const script = [
    `set +e`,
    unitName ? `systemctl stop ${shq(unitName)} >/dev/null 2>&1` : `true`,
    `docker rm -f ${shq(containerName)} >/dev/null 2>&1`,
    // Clear CONTENTS, not the directory itself — preserves ownership/perms a
    // family's own setupScript may have already `chown`ed (e.g. Conan/The
    // Isle), and the fresh setup script's own `mkdir -p` (where present)
    // still runs fine against an existing empty directory either way.
    ...hostDirs.map((d) => `rm -rf ${shq(d)}/* ${shq(d)}/.[!.]* ${shq(d)}/..?* 2>/dev/null`),
    `echo NXREINSTALL:WIPED`,
    gameSetup,
    `echo "NXREINSTALL:SETUP_RC:$?"`,
    `sleep 3`,
    unitName
      ? `st=$(systemctl is-active ${shq(unitName)} 2>/dev/null); echo "NXREINSTALL:STATE:${"$"}{st:-unknown}"`
      : `echo "NXREINSTALL:STATE:unknown"`,
  ].join("\n");

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, script, INSTALL_TIMEOUT_MS));
  const text = out.stdout;
  if (!/NXREINSTALL:WIPED/.test(text)) {
    await notify(server.userId, `Reinstall failed on ${server.hostname}`, "Could not stop/remove the existing game service before reinstalling — nothing was wiped.", href);
    throw new Error("game reinstall: wipe step did not run");
  }
  const setupRc = Number(/NXREINSTALL:SETUP_RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXREINSTALL:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (setupRc !== 0 || state !== "active") {
    await notify(
      server.userId,
      `${spec.label} reinstall did not come back up on ${server.hostname}`,
      `The old install was wiped, but the fresh one is "${state}" after setup (exit ${setupRc}). ` +
        `Check Console → Logs, or contact support — the old data has already been removed and cannot be recovered from this server.`,
      href
    );
    throw new Error(`game reinstall: setup rc=${setupRc} state=${state}`);
  }

  // Real port-bound confirmation — same discipline as gamePower/provisioning
  // (a systemd unit reporting "active" only proves the object exists, never
  // that the game process inside actually bound its port).
  const game = gamePortForServer(server);
  const checkHost = server.dedicatedIp?.address ?? server.node?.publicIp ?? null;
  if (game && checkHost) {
    const portCheck = await checkGamePortOpen(checkHost, game.port, game.protocol, {
      timeoutMs: GAME_REINSTALL_PORT_CHECK_TIMEOUT_MS,
      intervalMs: GAME_REINSTALL_PORT_CHECK_INTERVAL_MS,
      verifyBound: () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol),
    });
    if (!portCheck.ok) {
      await notify(
        server.userId,
        `${spec.label} reinstalled — still starting up on ${server.hostname}`,
        `The service is active, but nothing is answering on ${game.port}/${game.protocol} yet. A freshly pulled image's ` +
          `first boot can take a few minutes — check back shortly, or watch Console → Logs.`,
        href
      );
      // Not a hard failure: the wipe+setup both genuinely succeeded, this is
      // only the short best-effort confirmation window running out early.
      return;
    }
  }

  await notify(
    server.userId,
    `${spec.label} reinstalled on ${server.hostname}`,
    "The game was wiped and freshly reinstalled on this server. Your VPS itself was not touched or recreated.",
    href
  );
}

/**
 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
 * interval-based). Idempotent / safe on a timer.
 */
export async function gameScheduleSweep(): Promise<void> {
  const now = new Date();
  const due = await db.gameSchedule.findMany({
    where: { enabled: true, nextRunAt: { lte: now } },
    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
    take: 100,
  });
  if (due.length === 0) return;

  for (const s of due) {
    // Always advance the clock first so a server that is down / mid-operation does
    // not cause the same row to be reselected every tick.
    const nextRunAt = s.intervalMinutes
      ? computeNextIntervalRun(s.intervalMinutes, now)
      : computeNextRun(s.hour, s.minute, now);
    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});

    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
    if (!isGameFamily(fam)) continue;
    if (s.server.status !== "RUNNING") continue;

    if (s.kind === "command" && s.command) {
      // Send RCON command directly (e.g. save-all, weather clear).
      const spec = controlSpec(fam);
      if (!spec || spec.rcon === "none") continue;
      // Load full server for SSH access.
      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
      if (!server) continue;
      try {
        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
      } catch {
        // Best-effort: command schedules silently skip on failure.
      }
    } else {
      // Restart schedule: check for busy jobs first.
      const busy = await db.job.count({
        where: {
          serverId: s.server.id,
          status: { in: ["QUEUED", "RUNNING"] },
          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
        },
      });
      if (busy > 0) continue;

      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
    }
  }
}

/**
 * Track player join/leave events by comparing the live RCON player list against
 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
 *
 * For each RUNNING game server with a gamePlan:
 *   - NEW players (in RCON but no open session) → create a PlayerSession
 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
 *   - STILL ONLINE → no-op
 *
 * Per-server try/catch so one unreachable VM never blocks the sweep.
 */
export async function playerTrackingSweep(): Promise<void> {
  if (SANDBOX) return;

  const servers = await db.server.findMany({
    where: { status: "RUNNING", gamePlanId: { not: null } },
    select: CONTROL_FIELDS,
  });

  const now = new Date();

  for (const server of servers) {
    try {
      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
      if (!isGameFamily(fam)) continue;
      const spec = controlSpec(fam);
      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;

      // Get online players via RCON
      const res = await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, spec.listCommand!)
      );
      if (!res.ok) continue;
      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));

      // Get open sessions for this server
      const openSessions = await db.playerSession.findMany({
        where: { serverId: server.id, leftAt: null },
      });
      const sessionByName = new Map(
        openSessions.map((s) => [s.playerName.toLowerCase(), s])
      );

      // NEW players: in RCON but no open session
      for (const p of onlinePlayers) {
        if (!sessionByName.has(p.name.toLowerCase())) {
          await db.playerSession.create({
            data: { serverId: server.id, playerName: p.name },
          });
        }
      }

      // DEPARTED players: open session but not in RCON
      for (const session of openSessions) {
        if (!onlineNames.has(session.playerName.toLowerCase())) {
          await db.playerSession.update({
            where: { id: session.id },
            data: { leftAt: now },
          });
        }
      }
    } catch (e) {
      // Per-server: one failure must not break the sweep
      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
    }
  }
}

/** Close the oldest still-open PlayerSession for `playerName` on `serverId`. */
async function closeOpenLogSession(serverId: string, playerName: string, inferred: boolean): Promise<void> {
  const open = await db.playerSession.findFirst({
    where: { serverId, playerName: { equals: playerName, mode: "insensitive" }, leftAt: null },
    orderBy: { joinedAt: "asc" },
  });
  if (open) {
    await db.playerSession.update({ where: { id: open.id }, data: { leftAt: new Date(), leftAtInferred: inferred } });
  }
}

/**
 * Track player join/leave for game families with NO remote console (Valheim
 * today, via GAME_LOG_TRACKING in lib/game-control.ts) by tailing their own log
 * instead of RCON — `readGameLogs`, the exact same read-only path the Console
 * tab already uses. Runs every ~60s from the main loop, ALONGSIDE (not instead
 * of) `playerTrackingSweep` above — a server only ever matches one of the two,
 * since `logTrackingSpec` is only registered for families with `rcon: "none"`.
 *
 * THE REAL LIMITATION — read this before changing the inference below. Valheim's
 * dedicated-server log names a player on JOIN
 * (`Got character ZDOID from <name> : <id>`) but NOT on disconnect — a
 * disconnect only ever updates a running headcount (`... now N player(s)`). So
 * when the count drops we know FOR CERTAIN that one fewer player is connected,
 * but NOT which one. This sweep's handling of that gap:
 *
 *   - `onlineCount` always tracks the log's own headcount line exactly —
 *     ground truth, never guessed.
 *   - `onlineNames` (persisted on GameLogCursor) is a FIFO of names in join
 *     order. On a headcount decrement, the OLDEST believed-online name is
 *     popped and ITS PlayerSession is closed with `leftAtInferred: true` — a
 *     guess, not an observation, and wrong whenever the player who actually
 *     left isn't the longest-connected one of the group. `leftAtInferred` is
 *     surfaced in the UI (GamePlayerHistory) so this is never presented as
 *     fact.
 *   - If the count hits exactly 0, every remaining open session for the
 *     server is closed — that IS certain (nobody is connected), so those are
 *     NOT marked inferred.
 *   - If a JOIN names someone the FIFO still believes is online (drift from an
 *     earlier wrong guess), that stale session is closed first (inferred)
 *     before the fresh one opens, so drift self-corrects instead of piling up.
 *   - A count INCREASE with no matching join line parsed in this batch is left
 *     alone rather than inventing a name — `onlineCount` still updates.
 *
 * Incremental tailing: `GameLogCursor.lastLine` is the last raw line this sweep
 * already processed; each run only walks lines after that mark in the new tail.
 * `readGameLogs` is capped at the last 500 lines (lib/game-control.ts), so a
 * server producing >500 log lines between two ~60s sweeps could skip events —
 * acceptable for Valheim's actual join/leave volume, but worth knowing if this
 * pattern is reused for a chattier log. If the previous marker line has rolled
 * completely out of the new tail, this run processes nothing (rather than risk
 * double-counting) and just re-marks the newest line. On a server's very first
 * sweep (no GameLogCursor row yet) nothing is back-filled as a join — there is
 * no way to know when an already-connected player actually joined — so the
 * cursor is seeded silently and tracking starts clean from the next line on.
 */
export async function logPlayerTrackingSweep(): Promise<void> {
  if (SANDBOX) return;

  const servers = await db.server.findMany({
    where: { status: "RUNNING", gamePlanId: { not: null } },
    select: CONTROL_FIELDS,
  });

  for (const server of servers) {
    try {
      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
      if (!isGameFamily(fam)) continue;
      const spec = controlSpec(fam);
      const tracking = logTrackingSpec(fam);
      if (!spec || !tracking) continue; // only families with a registered log-tracking spec

      const logRes = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, 500));
      if (!logRes.ok) continue;
      const lines = logRes.lines;
      if (lines.length === 0) continue;

      const cursor = await db.gameLogCursor.findUnique({ where: { serverId: server.id } });
      const isFirstSweep = !cursor;

      let startIdx = lines.length; // default: process nothing (marker missing/rolled out)
      if (isFirstSweep) {
        startIdx = lines.length; // seed only — no back-fill, see doc comment
      } else if (cursor!.lastLine == null) {
        startIdx = 0; // a cursor existed but had no marker yet (shouldn't normally happen)
      } else {
        const idx = lines.lastIndexOf(cursor!.lastLine);
        startIdx = idx >= 0 ? idx + 1 : lines.length;
      }

      let onlineNames: string[] = Array.isArray(cursor?.onlineNames) ? [...(cursor!.onlineNames as unknown as string[])] : [];
      let onlineCount = cursor?.onlineCount ?? 0;

      for (let i = startIdx; i < lines.length; i++) {
        const line = lines[i];

        const joinM = tracking.joinRe.exec(line);
        if (joinM) {
          const name = joinM[1].trim();
          if (name) {
            const dupIdx = onlineNames.findIndex((n) => n.toLowerCase() === name.toLowerCase());
            if (dupIdx >= 0) {
              // FIFO drift: we thought they were already online. Close the
              // stale (inferred) session before opening the real new one.
              onlineNames.splice(dupIdx, 1);
              await closeOpenLogSession(server.id, name, true);
            }
            onlineNames.push(name);
            await db.playerSession.create({ data: { serverId: server.id, playerName: name } });
          }
          continue;
        }

        const countM = tracking.countRe.exec(line);
        if (countM) {
          const newCount = Number(countM[1]);
          if (Number.isFinite(newCount) && newCount !== onlineCount) {
            if (newCount === 0) {
              await db.playerSession.updateMany({
                where: { serverId: server.id, leftAt: null },
                data: { leftAt: new Date(), leftAtInferred: false },
              });
              onlineNames = [];
            } else if (newCount < onlineCount) {
              const drop = onlineCount - newCount;
              for (let d = 0; d < drop && onlineNames.length > 0; d++) {
                const leaver = onlineNames.shift()!;
                await closeOpenLogSession(server.id, leaver, true);
              }
            }
            onlineCount = newCount;
          }
        }
      }

      const lastLine = lines[lines.length - 1];
      await db.gameLogCursor.upsert({
        where: { serverId: server.id },
        create: { serverId: server.id, lastLine, onlineNames, onlineCount },
        update: { lastLine, onlineNames, onlineCount },
      });
    } catch (e) {
      console.error(`[log-player-tracking] sweep failed for server ${server.id}`, e);
    }
  }
}

