/**
 * How long GAME_POWER's post-action port check waits for the game process to
 * bind its port before giving up (`GameControlSpec.powerStartTimeoutMs` can
 * override this per family). Deliberately much shorter than provisioning's
 * GAME_PORT_CHECK_TIMEOUT_MS (300s) — this runs synchronously from a customer
 * pressing Start/Restart in the dashboard, not an unattended provision, and
 * most families that are going to come up at all do so in a few seconds once
 * systemd reports the unit active.
 *
 * CORRECTION (2026-09-30): this comment used to claim a slow family "only
 * delays the SUCCESS notification, never falsely reports failure early" — that
 * was wrong. On timeout this DOES throw, which fails the job and tells the
 * customer the start failed, even when the process goes on to come up fine a
 * moment later (real incident: a Terraria customer's start kept "failing"
 * while the server was actually booting normally — world load + "Settling
 * liquids" legitimately took longer than 30s). Any family whose real boot can
 * exceed this window needs `powerStartTimeoutMs` set on its `GameControlSpec`,
 * not just an assumption that 30s is always enough.
 */
const GAME_POWER_PORT_CHECK_TIMEOUT_MS = 30_000;
const GAME_POWER_PORT_CHECK_INTERVAL_MS = 3_000;

/**
 * Game server control-panel worker handlers.
 *
 * Registered in worker/index.ts:
 *   GAME_POWER:     gamePower,
 *   GAME_BACKUP:    gameBackup,
 *   GAME_REINSTALL: gameReinstall,
 * and `gameScheduleSweep()`, `playerTrackingSweep()` (RCON families) and
 * `logPlayerTrackingSweep()` (log-only families, e.g. Valheim) called on ~60s
 * timers.
 *
 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
 * and the root password is never surfaced in an error (only a trimmed remote stderr
 * is, which never contains it).
 *
 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
 */

const CONTROL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true, sshManagementKeyEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true } },
  osTemplate: { select: { family: true } },
  gamePlan: { select: { gameFamily: true } },
} as const;

type ControlServer = {
  id: string;
  userId: string;
  hostname: string;
  status: string;
  rootPassword: string | null;
  rootPasswordEnc: string | null;
  sshManagementKeyEnc?: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  node: { publicIp: string } | null;
  osTemplate: { family: string | null };
  gamePlan: { gameFamily: string | null } | null;
};

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-control] notify failed", e);
  }
}

function resolveSpec(server: ControlServer): GameControlSpec {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (!isGameFamily(fam)) throw new Error("not a game server");
  const spec = controlSpec(fam);
  if (!spec) throw new Error("no control spec for family");
  return spec;
}

/**
 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
 * the family's control spec (compile-time constants); `action` is one of the three
 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
 * a successful action (the same discipline as worker/game-update.ts).
 */
function powerScript(spec: GameControlSpec, action: string): string {
  const hints = spec.serviceHints.map(shq).join(" ");
  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");

  // Optional pre-restart announce over RCON (best-effort; never fails the action).
  if (action === "restart" && p.announce && spec.rcon === "source") {
    try {
      await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
      );
    } catch (e) {
      console.error("[game-control] restart announce failed (continuing)", e);
    }
  }

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
  const text = out.stdout;
  if (/NXGP:UNIT:NONE/.test(text)) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
    throw new Error("game power: no service unit found");
  }
  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (!/NXGP:END/.test(text) || rc !== 0) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
  }

  // FOUND LIVE 2026-09-20: this used to notify success on rc===0 + an END
  // marker alone, without ever checking `state` — so a unit that restarted
  // straight into "failed" (or stayed "activating"/crash-looping) was still
  // reported to the customer as "restarted (now failed)", i.e. success. A
  // `Restart=always` unit around a crash-looping container (exactly what a
  // wrong-Java-version Minecraft image produces — see
  // lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS) reports "active" between
  // crashes just as readily as a genuinely healthy server, so `systemctl`
  // alone was never going to be enough either way.
  if (action !== "stop" && state !== "active") {
    await notify(
      server.userId,
      `Could not ${action} the ${spec.label} service`,
      `${spec.label} on ${server.hostname} is "${state}" after the ${action}, not active. ` +
        `Diagnose with: systemctl status <unit> ; journalctl -u <unit> -n 50`,
      href
    );
    throw new Error(`game power: ${action} left service in state=${state}`);
  }

  // Real port-bound check — the same in-guest positive-confirmation path
  // PROVISION uses (worker/provision-health.ts's checkGamePortOpen +

/**
 * Post-boot health verification for PROVISION.
 *
 * WHY: two real customer-facing incidents shipped because PROVISION reported
 * DONE on "no API call threw", never "the customer can actually reach what got
 * built" — a VM whose IP collided with unrelated infrastructure (network-layer,
 * nothing ever reachable) and, separately, EVERY game family's `docker run -d`
 * setup script creates no systemd unit, so a game can fail to start while the
 * container still shows "Up" (confirmed: Terraria hung on an interactive
 * world-selection prompt with no TTY, port never bound). Both would have been
 * caught by one real end-to-end check: actually try to reach the server the
 * way a customer would, before ever calling it ready.
 *
 * This module holds the pure retry/resolution logic (unit-testable, see
 * test/provision-health.test.ts) plus the real TCP I/O. worker/index.ts's
 * `provision()` calls `checkSshReachable` / `checkGamePortOpen` and — matching
 * this codebase's established failed-PROVISION convention — simply THROWS on
 * failure; the existing `runJob` catch path takes it from there (retry while
 * attempts remain, else ERROR + release the dedicated IP + notify the
 * customer). This module never touches Server/Job rows itself.
 */
import net from "node:net";
import dgram from "node:dgram";
import { GAME_PORT, type GameFamily } from "../lib/games";
import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "../lib/ssh-exec";

// ---------------------------------------------------------------------------
// Pure retry math — no I/O, safe to unit test directly.
// ---------------------------------------------------------------------------

/**
 * How many attempts a retry window of `timeoutMs` at `intervalMs` cadence
 * allows, counting the first (immediate) attempt. Always at least 1, so a
 * misconfigured zero/negative timeout still tries once rather than looping
 * forever or never trying at all.
 */
export function attemptsFor(timeoutMs: number, intervalMs: number): number {
  if (!Number.isFinite(timeoutMs) || !Number.isFinite(intervalMs) || intervalMs <= 0) return 1;
  return Math.max(1, Math.floor(timeoutMs / intervalMs) + 1);
}

export type CheckOnce = () => Promise<{ ok: true; detail?: string } | { ok: false; error: string }>;

export type RetryResult =
  | { ok: true; detail?: string; attempts: number; elapsedMs: number }
  | { ok: false; error: string; attempts: number; elapsedMs: number };

/**
 * Generic bounded retry: call `checkOnce` up to `attemptsFor(timeoutMs,
 * intervalMs)` times, sleeping `intervalMs` between attempts, stopping early
 * on the first success. `sleep` is injectable so tests can run this at real
 * speed with zero wall-clock delay instead of mocking timers.
 */
export async function retryCheck(
  checkOnce: CheckOnce,
  opts: { timeoutMs: number; intervalMs: number; sleep?: (ms: number) => Promise<void>; now?: () => number }
): Promise<RetryResult> {
  const sleep = opts.sleep ?? ((ms: number) => new Promise((resolve) => setTimeout(resolve, ms)));
  const now = opts.now ?? (() => Date.now());
  const attempts = attemptsFor(opts.timeoutMs, opts.intervalMs);
  const start = now();
  let lastError = "no attempt was made";
  for (let i = 0; i < attempts; i++) {
    const res = await checkOnce();
    if (res.ok) return { ok: true, detail: res.detail, attempts: i + 1, elapsedMs: now() - start };
    lastError = res.error;
    if (i < attempts - 1) await sleep(opts.intervalMs);
  }
  return { ok: false, error: lastError, attempts, elapsedMs: now() - start };
}

// ---------------------------------------------------------------------------
// Game-family / port resolution — pure, no I/O.
// ---------------------------------------------------------------------------

export type ServerFamilyLike = {
  gamePlan?: { gameFamily?: string | null } | null;
  osTemplate?: { family?: string | null } | null;
};

/**
 * Resolve the game family for a server, same precedence as
 * lib/game-config.ts's `familyFor` (game plan first, OS template as
 * fallback) — but WITHOUT requiring a customization schema to exist, since
 * Terraria (this check's motivating incident) has no config schema yet is
 * still a game whose port must be verified. Returns null for a plain VPS or
 * an unrecognized family (never throws — an unknown family is a data/config
 * gap for the caller to log, not a health failure).
 */
export function gameFamilyForServer(server: ServerFamilyLike | null | undefined): GameFamily | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  return fam && Object.prototype.hasOwnProperty.call(GAME_PORT, fam) ? (fam as GameFamily) : null;
}

/** The expected game port + transport for a server, or null (not a recognized game). */
export function gamePortForServer(server: ServerFamilyLike | null | undefined): { port: number; protocol: "tcp" | "udp" } | null {
  const fam = gameFamilyForServer(server);
  return fam ? GAME_PORT[fam] : null;
}

// ---------------------------------------------------------------------------
// Real network I/O — single-attempt probes.
// ---------------------------------------------------------------------------

/** Default per-attempt socket timeout — how long ONE connect (not the whole
 *  retry window) is allowed before giving up and trying again. */
export const TCP_ATTEMPT_TIMEOUT_MS = 5_000;

/**
 * One TCP connect attempt, optionally requiring an SSH banner
 * ("SSH-2.0-...") rather than just a completed handshake — a closed port
 * that drops the connection can otherwise look indistinguishable from a real
 * refusal on some networks, so getting the actual banner is the proof.
 */
function tcpAttempt(
  host: string,
  port: number,
  opts: { timeoutMs: number; expectSshBanner: boolean }
): Promise<{ ok: true; detail?: string } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let settled = false;
    let buf = "";
    const finish = (result: { ok: true; detail?: string } | { ok: false; error: string }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners();
      socket.destroy();
      resolve(result);
    };
    const timer = setTimeout(() => finish({ ok: false, error: "timed out" }), opts.timeoutMs);
    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.once("connect", () => {
      if (!opts.expectSshBanner) finish({ ok: true });
      // else: wait for the banner line on "data" below.
    });
    if (opts.expectSshBanner) {
      socket.on("data", (chunk) => {
        buf += chunk.toString("utf8");
        if (buf.includes("\n") || buf.length >= 256) {
          const line = buf.trim();
          if (line.startsWith("SSH-")) finish({ ok: true, detail: line.slice(0, 120) });
          else finish({ ok: false, error: `connected but no SSH banner (got: ${line.slice(0, 80) || "<empty>"})` });
        }
      });
    }
    socket.connect(port, host);
  });
}

/**
 * One UDP reachability probe. UDP has no handshake, so this cannot PROVE a
 * listener exists the way a TCP connect can — but on Linux, a datagram sent
 * to a UDP port nothing is bound to draws a prompt ICMP port-unreachable,
 * which node surfaces as an `ECONNREFUSED` error on a *connected* UDP socket.
 * No error within the window is treated as reachable. This is the same class
 * of "did the process actually bind the port" evidence the TCP check gives —
 * it would have caught the Terraria-style bug (container up, nothing bound)
 * on a UDP-only game exactly the same way.
 */
function udpAttempt(host: string, port: number, opts: { timeoutMs: number }): Promise<{ ok: true } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const socket = dgram.createSocket("udp4");
    let settled = false;
    const finish = (result: { ok: true } | { ok: false; error: string }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners();
      socket.close();
      resolve(result);
    };
    const timer = setTimeout(() => finish({ ok: true }), opts.timeoutMs);
    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.connect(port, host, () => {
      socket.send(Buffer.from([0]), (err) => {
        if (err) finish({ ok: false, error: (err as NodeJS.ErrnoException).code ?? err.message });
      });
    });
  });
}

// ---------------------------------------------------------------------------
// Public checks used by worker/index.ts's provision().
// ---------------------------------------------------------------------------

/**
 * Retries every ~5s for up to 2 minutes. SSH normally comes up within
 * seconds of the guest booting — cloud-init's user/ssh-key modules run near
 * the START of boot, well before the game/app install `runcmd` — and by the
 * time provision() reaches this check it has usually already waited up to
 * 180s for the guest agent, so sshd has almost always had time. Two minutes
 * of its own headroom on top covers the case where the agent never answers
 * (not every image ships qemu-guest-agent) but sshd is merely slow.
 */
export const SSH_CHECK_TIMEOUT_MS = 120_000;
export const SSH_CHECK_INTERVAL_MS = 5_000;

/**
 * Real TCP connect + SSH banner check against the server's actual reachable
 * address (caller passes the dedicated IP, or the NAT host + assigned SSH
 * port — see worker/index.ts's `dedicated`/`sshPort` computation, reused
 * here rather than recomputed).
 */
export async function checkSshReachable(
  host: string,
  port: number,
  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
): Promise<RetryResult> {
  return retryCheck(() => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: true }), {
    timeoutMs: opts?.timeoutMs ?? SSH_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? SSH_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
  });
}

/**
 * Retries every 10s for up to 5 minutes (30 attempts). A game server takes
 * meaningfully longer than SSH to actually start listening — the setup
 * script still has to run AFTER boot (docker install if not cached, image
 * pull, first-run world/save generation) once cloud-init's `runcmd` fires.
 * 5 minutes is a principled default sized for a cold Docker image pull on
 * this host, not an empirically measured figure (no real order was placed
 * to time one for this change) — the timeout/interval are named exports so
 * they can be retuned in one place once real timings are observed.
 */
export const GAME_PORT_CHECK_TIMEOUT_MS = 300_000;
export const GAME_PORT_CHECK_INTERVAL_MS = 10_000;

/**
 * The 300s above is right for most of the catalog and hopeless for the rest.
 * First real measurements, from the 2026-09-06 whole-catalog sweep (the
 * "once real timings are observed" the comment above asked for):
 *
 *   minecraft 222s · palworld ~285s · rust ~310s · terraria 451s · valheim 456s
 *   ark       FAILS — 22.9 GB SteamCMD download, ~30 min before it binds a port
 *   cs2       FAILS — 71 GB download, over an hour (and needs a bigger disk)
 *
 * Terraria and Valheim already spend ~170-180s of the 300s budget inside the
 * game step, so the margin was thin even where it passed, and every large
 * Steam-based family fails outright — a HEALTHY server declared failed, which
 * is the same "the system asserting something untrue" class this whole health
 * check exists to prevent, just inverted.
 *
 * Raising the constant alone trades one wrong answer for another: a genuinely
 * dead server (the Terraria interactive-prompt bug) would keep a customer
 * waiting the whole time before failing. So instead, once the 300s check has
 * failed, provisioning asks the guest whether it is still WORKING — see
 * `waitOutGameInstall` in worker/index.ts. These bound that.
 *
 * `GAME_INSTALL_MAX_WAIT_MS` is a hard ceiling regardless of progress, sized
 * to cover ark comfortably; cs2 exceeds it and is blocked on disk sizing
 * anyway (see docs/DOCUMENTATION.md).
 */
export const GAME_INSTALL_MAX_WAIT_MS = 45 * 60_000;
/** One progress sample per minute — also the port-recheck window between samples. */
export const GAME_INSTALL_SAMPLE_MS = 60_000;
/** Disk growth under this between two samples does not count as progress (KB). */
export const GAME_INSTALL_MIN_GROWTH_KB = 8 * 1024;
/** Consecutive no-progress samples before giving up. */
export const GAME_INSTALL_STALL_LIMIT = 3;
/**
 * Restarts of the game's own systemd unit, accumulated DURING the extended
 * wait, that mean "crash loop" rather than "still installing".
 *
 * Why: `installProgressed` treats any container output inside the sample
 * window as work in progress — and a container that dies and is restarted by
 * systemd every few seconds produces output continuously, forever. So a
 * genuinely broken family never trips the stall detector and burns the entire
 * `GAME_INSTALL_MAX_WAIT_MS` ceiling on every one of its three attempts.
 * Measured on the families this catalog sweep found broken: Eco (caught at
 * NRestarts=30), Garry's Mod (61), The Forest (19 within nine minutes) — each
 * one made a customer watch "Installing the game…" for ~2.25 hours before
 * being told it failed, when the guest knew inside a minute.
 *
 * The generated unit (`wrapDockerGameService`) is `Restart=always`
 * `RestartSec=5`, and a healthy install never exits at all, so NRestarts stays
 * 0 for every family that works. Counting the DELTA since the wait began — not
 * the absolute value — keeps a container that legitimately restarted once or
 * twice during earlier setup from being judged on that history.
 */
export const GAME_INSTALL_RESTART_LIMIT = 3;

/**
 * Has the game's systemd unit restarted enough times DURING the extended wait
 * to call it a crash loop? A negative reading means "unknown" (no unit, or the
 * guest could not be asked) and is never treated as a crash — this check can
 * only ever end a wait early on positive evidence.
 */
export function gameUnitCrashLooping(firstRestarts: number, currentRestarts: number): boolean {
  if (!Number.isFinite(firstRestarts) || !Number.isFinite(currentRestarts)) return false;
  if (firstRestarts < 0 || currentRestarts < 0) return false;
  return currentRestarts - firstRestarts >= GAME_INSTALL_RESTART_LIMIT;
}

/** One reading of "is the guest still doing install work?" — see `installProgressed`. */
export type InstallSample = { usedKb: number; logBytes: number };

/**
 * Did the guest do any install work between two samples?
 *
 * Deliberately family-agnostic, so there is no per-image table to drift: either
 * the root filesystem grew by a real amount (a download or extract is running),
 * or the game container wrote to its log inside the sample window (world
 * generation, engine startup — work that need not move the disk much). Either
 * one counts; only both being absent means "stopped".
 */
export function installProgressed(prev: InstallSample, next: InstallSample): boolean {
  return next.usedKb - prev.usedKb >= GAME_INSTALL_MIN_GROWTH_KB || next.logBytes > 0;
}

/**
 * Real TCP-or-UDP connect check (per `GAME_PORT`'s `protocol`) against the
 * server's own address at the game's actual listen port — see
 * `gamePortForServer`. Reuses the caller's already-computed `ip` (the
 * dedicated public IP, or the NAT server's private address) rather than
 * recomputing it.
 *
 * NOTE on NAT servers: only SSH gets an automatic port-forward at provision
 * time (`syncPortForwardsBestEffort`); the game's own port is forwarded only
 * if the customer adds a `PortForward` for it (lib/actions-server.ts) — a
 * separate, pre-existing product gap this task does not touch. Checking
 * against the VM's own address (not the public NAT address) still verifies
 * the thing this check exists to catch — the game process itself bound the
 * port — independent of whether that port is yet forwarded to the internet.
 */
export async function checkGamePortOpen(
  host: string,
  port: number,
  protocol: "tcp" | "udp",
  opts?: {
    timeoutMs?: number;
    intervalMs?: number;
    sleep?: (ms: number) => Promise<void>;
    /**
     * Positive confirmation that the game really is bound to the port, read
     * from inside the guest — see `procNetHasPort` and the UDP note above.
     * `true` = bound, `false` = definitely not bound, `null` = could not tell
     * (never held against the server). Required to make the UDP path mean
     * anything; harmless and still useful as a second opinion for TCP.
     */
    verifyBound?: () => Promise<boolean | null>;
  }
): Promise<RetryResult> {
  const attempt: CheckOnce =
    protocol === "tcp"
      ? () => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: false })
      : () => udpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS });
  const verify = opts?.verifyBound;
  const checkOnce: CheckOnce = verify
    ? async () => {
        const r = await attempt();
        if (!r.ok) return r;
        const bound = await verify();
        if (boundVerdictPasses(protocol, bound)) return r;
        return {
          ok: false,
          error:
            bound === false
              ? `the ${port}/${protocol} probe drew no refusal, but nothing inside the guest is bound to ` +
                `${port}/${protocol} — silence is not the game listening`
              : `the ${port}/udp probe drew no refusal, but the guest could not confirm anything is bound ` +
                `to ${port}/udp — for UDP that is no evidence at all, not a pass`,
        };
      }
    : attempt;
  return retryCheck(checkOnce, {
    timeoutMs: opts?.timeoutMs ?? GAME_PORT_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? GAME_PORT_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
  });
}

/**
 * Is a socket bound to `port` present in a `/proc/net/{udp,udp6,tcp,tcp6}`
 * table? Pure parser over the raw table text so it is unit-testable; the
 * caller concatenates the guest's own tables plus each running container's
 * (`/proc/<pid>/net/...`), because a containerised game binds the port in its
 * OWN network namespace, not the guest's.
 *
 * WHY THIS EXISTS: `udpAttempt` resolves SUCCESS on timeout — for a
 * connectionless protocol there is nothing else a generic prober can do, since
 * a healthy game server has no obligation to answer a byte of nonsense. So the
 * UDP game-port check passed on silence, and silence is exactly what a guest
 * emits while a crash-looping container is between restarts (the packet is
 * dropped rather than refused). Caught live 2026-09-07: a The Forest order was
 * marked DONE and handed over as ready while its container had restarted 118
 * times, had never started the game at all ("Missing SERVER_STEAM_ACCOUNT_TOKEN
 * … Aborting server start"), and had nothing bound to any port. That is the
 * same "the system asserting something untrue" failure this whole module was
 * written to end, just on the protocol half nobody had checked.
 *
 * `st` is only meaningful for TCP (0A = LISTEN); UDP sockets have no listen
 * state, so a bound socket is all there is to find.
 */
/**
 * Given the in-guest binding verdict (`true` bound / `false` not bound / `null`
 * could not be determined), may this attempt count as the game port being open?
 *
 * The asymmetry between the protocols is the whole point. A completed TCP
 * connect is real evidence by itself, so the in-guest read is only a second
 * opinion and "could not ask" costs nothing. A UDP probe that draws no refusal
 * is NOT evidence — `udpAttempt` reports success on silence — so without an
 * in-guest answer the attempt has established nothing, and letting "unknown"
 * pass would put the check straight back to being a no-op that any transient
 * SSH hiccup unlocks. Attempts repeat across the whole retry window, so a blip
 * costs one attempt; only a guest that stays unreachable for the entire window
 * fails here, and that guest has a real problem regardless.
 */
export function boundVerdictPasses(protocol: "tcp" | "udp", bound: boolean | null): boolean {
  if (bound === true) return true;
  if (bound === false) return false;
  return protocol === "tcp";
}

export function procNetHasPort(table: string, port: number, opts?: { tcpListeningOnly?: boolean }): boolean {
  if (!Number.isInteger(port) || port <= 0 || port > 65535) return false;
  const want = port.toString(16).toUpperCase().padStart(4, "0");
  for (const line of table.split("\n")) {
    const f = line.trim().split(/\s+/);
    // sl local_address rem_address st ...
    if (f.length < 4 || !f[1]?.includes(":")) continue;
    const local = f[1];
    const cut = local.lastIndexOf(":");
    if (local.slice(cut + 1).toUpperCase() !== want) continue;
    if (opts?.tcpListeningOnly && f[3] !== "0A") continue;
    // A socket bound to loopback INSIDE the container is bound to a network
    // nobody else is on — not the docker bridge, not the guest, certainly not a
    // player. Found live on Soulmask, whose admin port sits on 127.0.0.1:18888
    // in its namespace while `-p 18888:18888/tcp` publishes it: docker-proxy
    // accepts and the backend dial is refused. Counting that as "bound" would
    // make this check agree with a port that is provably unreachable.
    if (isLoopbackAddrHex(local.slice(0, cut))) continue;
    return true;
  }
  return false;
}

/** Is a `/proc/net` hex local address a loopback one (127.0.0.0/8, ::1, or
 *  an IPv4-mapped loopback)? Addresses are little-endian per 4-byte word, so
 *  127.0.0.1 appears as `0100007F`. */
function isLoopbackAddrHex(addr: string): boolean {
  const up = addr.toUpperCase();
  if (up.length === 8) return up.slice(6, 8) === "7F";
  if (up.length === 32) {
    if (up === "00000000000000000000000001000000") return true; // ::1
    if (up.startsWith("0000000000000000FFFF0000")) return isLoopbackAddrHex(up.slice(24)); // ::ffff:127.x.x.x
    return false;
  }
  return false;
}

// ---------------------------------------------------------------------------
// In-guest positive confirmation — the only way to tell "the game process
// really bound its port" from "the container/service object exists".
// ---------------------------------------------------------------------------

/**
 * Ask the guest whether anything is really bound to the game's port — the
 * positive evidence `checkGamePortOpen`'s UDP path cannot get from outside
 * (see `procNetHasPort` for why silence is not proof).
 *
 * Reads the network namespace of every RUNNING container, falling back to the
 * guest's own only when no container is running. The fallback order matters
 * and is not a detail: `docker-proxy` binds every published port in the
 * guest's ROOT namespace for as long as the container is up, whether or not
 * the game inside ever listens — verified live on The Forest, whose guest
 * showed `0.0.0.0:27015` bound while the game had never started. Counting the
 * root namespace whenever a container runs would reproduce the very false
 * positive this function exists to remove. A `--network host` container is
 * unaffected: its namespace IS the root one.
 *
 * Exported from this side-effect-free module (rather than kept private in
 * worker/index.ts, where it originally lived) so `worker/game-control.ts` can
 * reuse the exact same in-guest check for GAME_POWER's start/restart —
 * importing worker/index.ts itself is unsafe anywhere else, since it runs a
 * top-level job-polling `main()` loop on import.
 *
 * ADDED TO GAME_POWER 2026-09-20: every existing health signal for
 * GAME_UPDATE and GAME_POWER start/restart only ever checked that the
 * container/systemd-service OBJECT existed and `systemctl` reported it
 * active — never that the actual game process bound its port. That is
 * precisely how a Minecraft server hardcoded onto the wrong Java image
 * (crash-looping every ~15s, `docker logs` full of a clear Java-version
 * error) went undetected: the systemd unit around a `Restart=always`
 * container reports "active" between crashes just as readily as it would for
 * a genuinely healthy server. See lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS
 * for the incident this shares its root cause with.
 *
 * Opens its own SSH connection (does not reuse a caller's already-open one) —
 * pure reads, nothing on the guest is touched.
 *
 * Returns `null` — never `false` — for anything it could not determine (SSH
 * failed, no marker in the output), so an unreachable guest can never turn a
 * healthy server into a falsely-failed check.
 */
export async function gamePortBoundInGuest(
  probeServer: { id: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
  port: number,
  protocol: "tcp" | "udp"
): Promise<boolean | null> {
  const base = protocol === "tcp" ? "tcp" : "udp";
  try {
    return await withServerSsh(probeServer as any, async (conn) => {
      const r = await exec(
        conn,
        // `docker ps` failing and `docker ps` finding nothing look identical in
        // its output, so its exit status is captured explicitly: a daemon that
        // could not be asked must read as UNKNOWN, never as "no containers, so
        // look in the root namespace" — where docker-proxy would answer for a
        // dead game.
        `if ids=$(docker ps -q 2>/dev/null); then dok=1; else dok=0; fi; ` +
          `files=""; ` +
          `for pid in $(docker inspect -f '{{.State.Pid}}' ${"$"}ids 2>/dev/null); do ` +
          `case "${"$"}pid" in ''|0) continue;; esac; ` +
          `files="${"$"}files /proc/${"$"}pid/net/${base} /proc/${"$"}pid/net/${base}6"; done; ` +
          `if [ -z "${"$"}files" ]; then ` +
          `if [ "${"$"}dok" = 1 ] && [ -z "${"$"}ids" ]; then files="/proc/net/${base} /proc/net/${base}6"; ` +
          `else echo NXNET_UNKNOWN; exit 0; fi; fi; ` +
          `echo NXNET_BEGIN; cat ${"$"}files 2>/dev/null; echo NXNET_END`,
        QUICK_TIMEOUT_MS
      );
      const begin = r.stdout.indexOf("NXNET_BEGIN");
      const end = r.stdout.indexOf("NXNET_END");
      if (begin < 0 || end < begin) {
        console.warn(
          `[worker] ${probeServer.id}: could not read ${port}/${protocol} bindings from the guest ` +
            `(${r.stdout.includes("NXNET_UNKNOWN") ? "docker could not be queried" : "no marker in the reply"})`
        );
        return null;
      }
      const table = r.stdout.slice(begin + "NXNET_BEGIN".length, end);
      const bound = procNetHasPort(table, port, { tcpListeningOnly: protocol === "tcp" });
      if (!bound) {
        console.warn(`[worker] ${probeServer.id}: nothing in the guest is bound to ${port}/${protocol}`);
      }
      return bound;
    });
  } catch (e) {
    console.warn(
      `[worker] ${probeServer.id}: could not ask the guest about ${port}/${protocol} bindings: ${String((e as Error)?.message ?? e)}`
    );
    return null;
  }
}

// (the honest fix), not to re-add a blanket floor here (the thing that hid
// this exact problem in the first place).
const effectiveBaseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
const cfg: Record<string, any> = {
  cores: effectiveCores,
  memory: effectiveRamMB,
  balloon: balloonFloorMB(effectiveRamMB),
  ciuser: "root",
  cipassword: password,
  sshkeys,
  nameserver: "1.1.1.1 8.8.8.8",
  onboot: 1,
  // Omit cicustom (rather than deleting it) when there's no fresh per-VM
  // snippet to point it at — see the long comment above ("Configuring the
  // network…") for why the template's own inherited value must survive
  // here, not be cleared. It only works correctly because every onboarded
  // node's templates have a valid, node-scoped storage reference for it
  // (fixed 2026-09-05 after the templates migrated from primary carried the
  // wrong storage name).
  ...(cicustom ? { cicustom } : {}),
  tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
};
if (dedicated && dedicated.virtualMac) {
  // Public bridge + a real bound Virtual MAC. OVH: from its Virtual MAC
  // API. Hetzner: from Robot's `/ip/{ip}/mac` (corrected 2026-09-29 —
  // allocateDedicatedIp() used to hardcode "" for Hetzner on the mistaken
  // belief it had no such mechanism; it does, and Hetzner's own
  // network-abuse filtering actively polices this — see lib/hetzner.ts's
  // header comment for the real incident). Either way: failover/additional
  // IP as /32 with the provider's gateway for it.
  cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
  cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
} else if (dedicated) {
  // Best-effort fallback ONLY — reached when Hetzner's MAC lookup/create
  // itself failed (allocateDedicatedIp logs loudly and returns "" rather
  // than blocking a paying customer's order over it). Still forces the
  // public bridge explicitly rather than trusting the clone's inherited
  // bridge: node-2's (and any onboard-node.sh node's) templates default to
  // the isolated, NAT-only vmbr1, which has no path to a real public IP at
  // all — confirmed live 2026-09-29, the first real bug found here, fixed
  // separately from the MAC issue above. Proxmox auto-assigns a MAC when
  // none is given; it will NOT be Hetzner-registered, so this guest may
  // still trip Hetzner's abuse filter until the MAC lookup/create above
  // succeeds on a later attempt.
  cfg.net0 = `virtio,bridge=vmbr0`;
  cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
} else {
  // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
  cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
}
await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);

// Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
// customer bought as a deploy-time upsell, so the VM is born the right size and
// no separate DISK_EXPAND job is needed on a fresh order.
await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
  disk: "scsi0",
  size: `${effectiveDiskGB(effectiveBaseDiskGB, server.extraDiskGB)}G`,
});

// Port forwarding is what makes the `ssh root@host -p <port>` line below true
// for a NAT server. If it cannot be proved, the readiness message says so
// instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
// VM itself is fine and a failed PROVISION would flip it to ERROR and release
// its IP, which is a worse outcome than a missing forward.
let natError: Error | null = null;
if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);

// Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
// AFTER the VM was already created and started; the reaper then re-queues the job.
// Starting an already-running VM makes Proxmox's start task fail with "already
// running", which — before this guard — stranded a perfectly good, reachable VM in
// ERROR forever (every retry hit the same wall). So skip the start when the VM is
// already running, and treat an "already running" race as success rather than fatal.
const alreadyRunning = await conn
  .vmStatus(vmid)
  .then((s: { status?: string } | null) => s?.status === "running")
  .catch(() => false);
if (!alreadyRunning) {
  await step("Starting your server…");
  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  try {
    await conn.waitForTask(startUpid);
  } catch (e) {
    if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
  }
}

// `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
// agent whether the machine actually booted before calling it ready (M7 #10).
// A false here is reported, never downgraded into silence.
if (!SANDBOX) await step("Booting the operating system…");
const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);

// Real end-to-end reachability check — the guest agent above proves only that
// QEMU's in-guest daemon answered (and plenty of images don't even ship it, see
// the `booted` caveat below). Neither that nor `waitForTask` proves a customer
// can actually reach the thing we are about to call "ready". Two real incidents
// shipped without this: a VM whose IP collided with unrelated infrastructure
// (nothing was ever reachable), and separately every game family's
// `docker run -d` setup script creates no systemd unit, so the game process can
// silently fail to start while the container still shows "Up" (confirmed:
// Terraria hung on an interactive world-selection prompt with no TTY, port
// never bound) — PROVISION reported success both times. This throws on
// failure, same as every other fatal step above: the existing `runJob` catch
// path (retry while attempts remain, else ERROR + release the dedicated IP +
// `notifyProvisionFailed`) handles it, and because this runs BEFORE the
// status flip to RUNNING and the deployment email below, neither ever fires
// for a server that failed this check.
if (!SANDBOX) {
  // Same address a customer would use: the dedicated IP if one was allocated,
  // else the NAT host's public IP + this server's assigned SSH port — reusing
  // `dedicated`/`sshPort` computed earlier rather than recomputing them (see
  // the identical `sshLine` construction below).
  const sshHost = dedicated ? dedicated.address : (server.node?.publicIp ?? process.env.PUBLIC_IP);
  const sshCheckPort = dedicated ? 22 : (sshPort ?? 22);
  await step("Waiting for network access…");
  const ssh = await checkSshReachable(sshHost!, sshCheckPort);
  if (!ssh.ok) {
    throw new Error(
      `SSH did not respond on ${sshHost}:${sshCheckPort} after ~${Math.round(ssh.elapsedMs / 1000)}s ` +
        `(${ssh.attempts} attempt(s); last error: ${ssh.error}). The VM started, but nothing answered SSH, ` +
        `so this server cannot be handed to the customer as ready.`
    );
  }

  const game = gamePortForServer(server as unknown as ServerFamilyLike);
  if (game) {
    // The one genuinely game-specific checkpoint: the guest is up and SSH
    // answers, but the game process itself may still be pulling its image and
    // starting its container before its own port opens — a real, observable
    // distinction (not present at all for a plain VPS order), unlike "pulling
    // the image" itself, which happens inside the guest's own cloud-init run
    // with no channel back to this worker to report on.
    await step("Starting the game server…");

    // `ip` (the guest's own private address) only works as a check target on
    // the PRIMARY: the worker always runs there, sharing that node's own
    // bridge network, so a direct connect to 10.20.0.x succeeds. Any OTHER
    // node is a separate NAT island by design (see the multi-node docs) —
    // the primary has NO route to a non-primary node's private subnet at
    // all, so checking `ip` directly there fails with EHOSTUNREACH 100% of
    // the time, regardless of whether the game server is healthy. Found
    // live: the very first real customer ever freshly provisioned onto
    // node-2 hit this unconditionally — SSH passed (it already correctly
    // checks the public address), the game-port check could not, ever.
    // Fix: for a NAT (non-dedicated) server on a non-primary node, forward
    // the port FIRST (reusing an existing forward on retry rather than
    // allocating a new public port every attempt) and check through it via
    // the node's own public IP — the exact same external path a real
    // customer uses, already proven to work by the SSH check just above.
    let checkHost = ip;
    let checkPort = game.port;
    if (!SANDBOX && !dedicated && !nodeRow?.isPrimary) {
      const existing = await db.portForward.findFirst({
        where: { serverId: server.id, guestPort: game.port, protocol: game.protocol },
        select: { publicPort: true },
      });
      checkPort = existing?.publicPort ?? (await allocateGameForward(server.nodeId, server.id, game.port, game.protocol));
      const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
      if (natErr) {
        throw new Error(
          `could not sync the game port forward on ${nodeRow?.name ?? "the target node"} for verification: ${natErr}`
        );
      }
      checkHost = server.node?.publicIp ?? process.env.PUBLIC_IP ?? ip;
    }

    // Same connection details the SSH check above just proved work — taken
    // from this run's own variables, NOT the stale `server` row (see
    // waitOutGameInstall's own comment for why that matters).
    const probeServer = {
      id: server.id,
      rootPassword: password,
      rootPasswordEnc: null,
      sshPort: dedicated ? 22 : sshPort,
      dedicatedIp: dedicated ? { address: dedicated.address } : null,
      node: server.node,
    };
    // The external probe alone cannot pass a UDP family honestly — it reports
    // success on silence. Pair it with positive evidence from inside the guest.
    const verifyBound = () => gamePortBoundInGuest(probeServer, game.port, game.protocol);

    const gameCheck = await checkGamePortOpen(checkHost, checkPort, game.protocol, { verifyBound });
    if (!gameCheck.ok) {
      // Not necessarily broken — it may just be BIG. ark pulls 22.9 GB from
      // SteamCMD and takes ~30 minutes before it binds a port; the 300s check
      // above cannot tell that apart from Terraria sitting dead on an
      // interactive prompt. Ask the guest which one this is.
      const still = await waitOutGameInstall(
        probeServer,
        checkHost,
        checkPort,
        game.protocol,
        step,
        controlSpec(gameFamilyForServer(server as unknown as ServerFamilyLike) ?? "")?.serviceHints[0] ?? null,
        verifyBound
      );
      if (!still.ok) {
        throw new Error(
          `game port ${game.port}/${game.protocol} never opened on ${checkHost}:${checkPort} after ` +
            `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
            `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
            `server cannot be handed to the customer as ready. ${still.reason}`
        );
      }
      console.log(`[worker] ${server.hostname}: game port opened after the extended install wait (${still.reason})`);
    }
    // Auto-forward THE PORT A PLAYER ACTUALLY JOINS ON for NAT (non-dedicated-IP)
    // servers. "Plug and play": every game server is reachable the moment it's
    // handed to the customer instead of requiring a manual PortForward from the
    // dashboard first. Found live: a real paying Minecraft customer with no
    // dedicated IP and zero forwards had no path from any public IP to their
    // game port at all. Dedicated IP servers need no forward — their guest port
    // already IS the public port.
    //
    // This is `joinPortFor`, NOT `game.port`. `GAME_PORT` is a health-CHECK map:
    // where an image exposes a TCP port it prefers that one, because a TCP
    // connect is real evidence the game process bound it. For eight families
    // (rust, ark, projectzomboid, factorio, arkasa, soulmask, squad, kf2) that
    // port is RCON/query/admin and the join port is a different, UDP one —

  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  if (/not a supported game server|not enabled|not available|not running|in progress/i.test(msg)) return msg.slice(0, 200);
  if (/timed out|reachable|root password/i.test(msg)) return msg.slice(0, 200);
  return "Could not reach the game server. Please try again shortly.";
}

