 * Exports: `familyFor`, `schemaFor`, `validateConfig` plus the `GAME_CONFIG_SCHEMAS`
 * table and its types.
 */

/** Bump when the field set changes in a way the worker/apply step must notice. */
export const GAME_CONFIG_VERSION = 1;

export type FieldType = "enum" | "bool" | "int" | "string";

/**
 * When a setting takes effect:
 *  - "deploy": needs a server restart / redeploy (world seed, tickrate, …)
 *  - "live":   can be pushed to a running server (motd, pvp, max players, …)
 * MVP treats both the same (simulated apply) but the UI surfaces the distinction.
 */
export type FieldPhase = "deploy" | "live";

export type ConfigField = {
  /** The game's own config key (e.g. "max-players", "ServerPlayerMaxNum"). */
  key: string;
  label: string;
  /** UI grouping heading. */
  group: string;
  type: FieldType;
  default: string | number | boolean;
  /** enum only — {value,label} choices. */
  options?: { value: string; label: string }[];
  /**
   * enum only. When true and `options` is long, the settings UI renders a
   * type-to-filter combobox (components/customer/SearchableSelect.tsx)
   * instead of a plain native `<select>` — a flat dropdown of 100+ entries
   * has no usable way to find one. Leave unset for short option lists
   * (gamemode, difficulty, …), where a native select is simpler and fine.
   */
  searchable?: boolean;
  /** int only — inclusive bounds. */
  min?: number;
  max?: number;
  phase: FieldPhase;
  /** optional one-line helper shown under the field. */
  help?: string;
  /**
   * string fields only. When true, `validateConfig` rejects a blank value —
   * used for values with no sane platform default where the server is
   * genuinely non-functional / unjoinable without a customer-supplied
   * credential (e.g. DST's Klei cluster TOKEN — an online DST cluster
   * refuses to start at all without one). Enforced both at order-creation
   * time (lib/game-order.ts, BEFORE payment) and at settings-save time
   * (lib/actions-game-config.ts), so it gates checkout AND blocks a customer
   * from blanking it back out later. See DST.TOKEN below for the motivating
   * incident (added same-day as the family, 2026-08-31 audit).
   */
  required?: boolean;
  /**
   * Override the docker `-e KEY=` name that `applyGameConfigEnv`
   * (worker/game-variant.ts) substitutes into, when it differs from `key`.
   *
   * Found live 2026-09-11: Valheim's World Name field is keyed `"world"` (a
   * readable schema key, matches the game's own `-world` flag name) but the
   * lloesche/valheim-server image's actual env var is `WORLD_NAME`.
   * `applyGameConfigEnv` matches literally on `field.key`, so `-e world=`
   * never appeared in the setup script and the customer's chosen world name
   * was silently dropped at provisioning — every Valheim server booted on
   * the catalog's hardcoded default world regardless of what was ordered.
   * Set this whenever a field's readable schema key isn't the literal env
   * var name the image expects.
   */
  envKey?: string;
};

export type GameVariant = {
  id: string;
  label: string;
  description?: string;
};

export type FamilySchema = {
  family: string;
  label: string;
  variants: GameVariant[];
  defaultVariant: string;
  fields: ConfigField[];
};

// ---------------------------------------------------------------------------
// Minecraft version -> required Java runtime (itzg/minecraft-server image tag)
// ---------------------------------------------------------------------------

/**
 * Minimum Java major version each range of Minecraft releases genuinely
 * needs, per Mojang's own real cutovers (minecraft.wiki/w/Tutorials/
 * Update_Java, confirmed live 2026-09-20). Sorted newest-cutover-first; the
 * first entry whose `min` is <= the target version wins.
 *
 * FOUND LIVE 2026-09-20: `worker/game-config.ts`'s MINECRAFT_IMAGE was a
 * single hardcoded `itzg/minecraft-server:java21` for every Minecraft server
 * regardless of chosen VERSION, and `prisma/catalog.ts`'s provisioning
 * setupScript baked the identical literal tag in directly — only the
 * `VERSION` env var itself was ever substituted per-customer
 * (`applyGameConfigEnv`), never the image. 26.1 and newer (offered below in
 * MINECRAFT_RELEASE_VERSIONS) requires Java 25; Java 21 cannot run it at all.
 * Confirmed live via server minecraft-qj4rxt (customer picked 26.2): `docker
 * logs mc` -> "Minecraft 26.1 and newer requires running the server with Java
 * 25 or above.", container never actually started, every existing health
 * check (GAME_UPDATE/GAME_POWER) saw only "the container/service object
 * exists" and never noticed.
 *
 * Checked itzg/docker-minecraft-server's own docs (docs/versions/java.md) for
 * whether the image can auto-select the right JDK from the requested
 * VERSION — it explicitly cannot: tags are static per-Java-version, and the
 * docs point at this same Minecraft-wiki table for the mapping rather than
 * doing it themselves. `latest`/`stable` DO auto-track whichever Java the
 * newest release needs (java25 today) — but floating with whatever Mojang
 * ships next is exactly the footgun already fixed here once, for the VERSION
 * field itself (the 2026-09-06 Cobblemon incident — see MINECRAFT.fields'
 * VERSION comment below): an unannounced future Java bump on those tags
 * customer before they type, instead of after the job fails; the worker imports
 * the same constant, so the two cannot drift.
 */
// `dayz` deliberately absent: `applyDayZ` (worker/game-config.ts) is fully
// written — serverDZ.cfg is genuinely file-based, patched via
// `updateDayZConfig`, unit-tested against a real reference cfg file (see
// test/dayz-config.test.ts) — but has NOT been confirmed live against a
// running container, because no Steam account exists in this environment to
// boot one (see lib/dayz-steam.ts). Add "dayz" here only after that live
// verification actually happens, per applyDayZ's own comment.
export const REAL_APPLY_FAMILIES = new Set<string>(["palworld", "minecraft", "rust", "valheim", "bedrock"]);

/** Whether a family's saved settings will really reach the game server. */
export function canApplyConfig(family: string | null | undefined): boolean {
  return !!family && (process.env.ENABLE_REAL_GAMECFG === "1" || REAL_APPLY_FAMILIES.has(family));
}

export function familyFor(server: ServerLike | null | undefined): string | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam && GAME_CONFIG_SCHEMAS[fam]) return fam;
  return null;
}

/** The customization schema for a family, or null. */
export function schemaFor(family: string | null | undefined): FamilySchema | null {
  if (!family) return null;
  return GAME_CONFIG_SCHEMAS[family] ?? null;
}

/** True if `variant` is a valid variant id for `family`. */
export function isValidVariant(family: string, variant: string): boolean {
  const s = GAME_CONFIG_SCHEMAS[family];
  return !!s && s.variants.some((v) => v.id === variant);
}

export type ValidateResult =
  | { ok: true; values: Record<string, string | number | boolean> }
  | { ok: false; error: string };

/**
 * Validate & coerce a settings object against a family's field schema. Unknown
 * keys are dropped; missing keys fall back to the field default. Returns a clean,
 * fully-populated values object ready to persist to `Server.gameConfig`.
 */
export function validateConfig(
  family: string,
  values: Record<string, unknown> | null | undefined
): ValidateResult {
  const schema = GAME_CONFIG_SCHEMAS[family];
  if (!schema) return { ok: false, error: `Unknown game family "${family}".` };

  const input = values ?? {};
  const out: Record<string, string | number | boolean> = {};

  for (const field of schema.fields) {
    const raw = input[field.key];
    const provided = raw !== undefined && raw !== null;

    switch (field.type) {
      case "bool": {
        out[field.key] = provided ? raw === true || raw === "true" || raw === "on" : (field.default as boolean);
        break;
      }
      case "int": {
        let n = provided ? Number(raw) : (field.default as number);
        if (!Number.isFinite(n)) return { ok: false, error: `${field.label} must be a number.` };
        n = Math.trunc(n);
        if (field.min !== undefined && n < field.min)
          return { ok: false, error: `${field.label} must be at least ${field.min}.` };
        if (field.max !== undefined && n > field.max)
          return { ok: false, error: `${field.label} must be at most ${field.max}.` };
        out[field.key] = n;
        break;
      }
      case "enum": {
        const v = provided ? String(raw) : String(field.default);
        if (!field.options?.some((o) => o.value === v))
          return { ok: false, error: `Invalid value for ${field.label}.` };
        out[field.key] = v;
        break;
      }
      case "string": {
        const v = provided ? String(raw) : String(field.default);
        if (field.required && v.trim().length === 0) {
          return {
            ok: false,
            error: `${field.label} is required.${field.help ? ` ${field.help}` : ""}`,
          };
        }
        if (v.length > 256) return { ok: false, error: `${field.label} is too long (max 256 chars).` };
        // CONFIG INJECTION: these values are written verbatim into LINE-ORIENTED
        // files on the customer's VM by worker/game-config.ts —
        // `server.properties` (`motd=<value>`), Rust's `server.cfg`
        // (`server.hostname "<value>"`) and Valheim's launch-args file. A newline
        // therefore does not set one option, it appends arbitrary further
        // options: a motd of "hi\nenable-rcon=true\nrcon.password=x" turns RCON
        // on with a chosen password, and that password is then read back out of
        // the same file and interpolated into an `mcrcon` command line.
        // `enum`/`int`/`bool` are constrained by their own branches; `string` was
        // the only field type with no allowlist at all, so it is checked here —
        // at the one point every caller (UI, server action and worker re-validation)
        // already goes through.
        // eslint-disable-next-line no-control-regex
        if (/[\x00-\x1f\x7f]/.test(v)) {
          return {
            ok: false,
            error: `${field.label} may not contain line breaks or control characters.`,
          };
        }
        out[field.key] = v;
        break;
      }
    }
  }

  return { ok: true, values: out };
}

