/**
 * Game runtime truth — PURE logic (no SSH, no DB, no clock of its own).
 *
 * WHY THIS EXISTS (incident 2026-09-30, server minecraft-6b88z1 / "tomatikk",
 * full write-up in docs/DOCUMENTATION.md): the game service was stopped, the
 * customer's dashboard said "Online" with live RAM/CPU/uptime, the Start
 * button was disabled, and players got "Connection timed out". Three separate
 * defects lined up:
 *
 *  1. "Online" was derived from `Server.status === "RUNNING"` — the VM's power
 *     state. The VM was fine. The game inside it was not running.
 *  2. The one signal that knew better (`gameConfig._serviceState`, written by
 *     GAME_POWER) was WIPED by the very next settings save, because
 *     `saveGameConfig` replaced the whole JSON blob with the schema values.
 *  3. The Start/Stop/Restart buttons followed that same VM-derived `running`
 *     flag, so the one control that would have fixed it was greyed out.
 *
 * This module defines a real game runtime state from a cheap in-guest probe
 * (systemd unit state + docker container state + "is the game port bound in
 * the game's own network namespace") plus the owner's recorded run intent,
 * and derives everything the UI needs from it: the badge, its tone, and which
 * power controls are available. The rule that matters most: when we do not
 * KNOW, we never say "Online" and we never hide Start.
 *
 * Covered by test/game-runtime.test.ts (including `sh -n` over the probe).
 */

// ---------------------------------------------------------------------------
// States
// ---------------------------------------------------------------------------

export type GameRuntimeState =
  /** service active, game port bound (and the public path answered when checked) */
  | "online"
  /** service active and the container is running, but the port could not be read */
  | "unverified"
  /** unit activating, or active with the port not bound yet inside the start grace */
  | "starting"
  /** active past the start grace with nothing bound — or bound but unreachable from outside */
  | "not_responding"
  /** service inactive AND the owner/admin asked for that */
  | "stopped"
  /** service inactive with no stop intent on record — the tomatikk state */
  | "game_stopped"
  /** unit failed, or the container is crash-looping */
  | "crashed"
  /** no probe, probe failed, or the probe could not find the game at all */
  | "unknown";

export const GAME_RUNTIME_STATES: readonly GameRuntimeState[] = [
  "online",
  "unverified",
  "starting",
  "not_responding",
  "stopped",
  "game_stopped",
  "crashed",
  "unknown",
];

/** States in which the game process is (believed to be) up. */
export const GAME_UP_STATES: ReadonlySet<GameRuntimeState> = new Set(["online", "unverified", "starting", "not_responding"]);

/**
 * States the fleet sweep treats as "the VM is up but the game is down" — only
 * meaningful when nobody asked for it (`stopped` is deliberately absent).
 */
export const GAME_DOWN_STATES: ReadonlySet<GameRuntimeState> = new Set(["game_stopped", "crashed", "not_responding"]);

/**
 * How long after the game (container/unit) started we still call an unbound
 * port "starting" rather than "not responding". The 2026-09-06 catalog sweep
 * measured first boots up to ~450s (Terraria/Valheim) and GAME_POWER allows
 * 180s for Minecraft/Valheim/Terraria; a warm restart is far faster. 6 minutes
 * is a deliberate middle: long enough not to cry wolf on a normal boot.
 */
export const START_GRACE_MS = 6 * 60_000;

/** A probe older than this is shown as "as of N min ago" and refreshed. */
export const RUNTIME_REFRESH_TTL_MS = 60_000;
/** A probe older than this is not trusted to drive the badge at all. */
export const RUNTIME_STALE_MS = 15 * 60_000;

export type RunIntent = "running" | "stopped";
export type IntentSource = "customer" | "admin" | "schedule" | "auto-restart" | "config" | "update" | "provision";

export function intentForPowerAction(action: string): RunIntent | null {
  if (action === "stop") return "stopped";
  if (action === "start" || action === "restart") return "running";
  return null;
}

// ---------------------------------------------------------------------------
// Probe — the remote script and its parser
// ---------------------------------------------------------------------------

/** Unit-name hint / family tokens that may reach the probe script. */
const TOKEN_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;

/**
 * The read-only in-guest probe. One SSH exec, a handful of `systemctl` /
 * `docker inspect` reads and two /proc tables — cheap enough to run for the
 * whole fleet every couple of minutes, and changes nothing on the guest.
 *
 * Shape follows the platform's own conventions:
 *  - the unit is resolved from the family's controlSpec hints exactly like
 *    GAME_POWER resolves it (so the probe and the buttons always agree);
 *  - the container name is read off the unit itself (`ExecStart=docker start
 *    -a <name>`, the shape wrapDockerGameService installs) — never guessed;
 *  - the port table is read from the CONTAINER's own namespace, never the
 *    guest root namespace while a container runs, because docker-proxy binds
 *    every published port there whether or not the game listens (the false
 *    positive worker/provision-health.ts's gamePortBoundInGuest documents);
 *  - markers are the contract (`NXRT:END`), not the exit code.
 *
 * `hints`/`family` are compile-time constants from lib/game-control.ts and are
 * re-validated here against a shell-inert allowlist anyway.
 */
export function runtimeProbeScript(opts: { hints: string[]; family: string; protocol: "tcp" | "udp" }): string {
  const hints = opts.hints.filter((h) => TOKEN_RE.test(h));
  if (!TOKEN_RE.test(opts.family)) throw new Error(`unsafe family token: ${opts.family}`);
  if (hints.length === 0) throw new Error("no service hints");
  const base = opts.protocol === "udp" ? "udp" : "tcp";
  const $ = "$";
  return [
    `say() { printf 'NXRT:%s\\n' "$1"; }`,
    `unit=""`,
    `for c in ${hints.join(" ")}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --all --plain --no-legend 2>/dev/null | grep -i ${opts.family} | head -1 | awk '{print $1}'); fi`,
    `say "UNIT:${$}{unit:-NONE}"`,
    `c=""`,
    `if [ -n "$unit" ]; then`,
    `  st=$(systemctl is-active "$unit" 2>/dev/null); say "SVC:${$}{st:-unknown}"`,
    `  say "NRESTARTS:$(systemctl show "$unit" -p NRestarts --value 2>/dev/null)"`,
    `  say "SINCE:$(systemctl show "$unit" -p ActiveEnterTimestamp --value 2>/dev/null)"`,
    `  c=$(systemctl cat "$unit" 2>/dev/null | sed -n 's/.*docker start -a \\([A-Za-z0-9_.-]*\\).*/\\1/p' | head -1)`,
    `fi`,
    `say "CTR:${$}{c:-NONE}"`,
    `pid=""`,
    `if [ -n "$c" ]; then`,
    `  ci=$(docker inspect -f '{{.State.Status}}|{{.State.StartedAt}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}|{{.State.Pid}}' "$c" 2>/dev/null)`,
    `  say "CSTATE:${$}{ci:-NONE}"`,
    `  pid=$(printf '%s' "$ci" | awk -F'|' '{print $4}')`,
    `fi`,
    `files=""`,
    `case "$pid" in ''|0) ;; *) files="/proc/$pid/net/${base} /proc/$pid/net/${base}6";; esac`,
    // No container at all (a non-docker family): the guest's own namespace is
    // the game's namespace. A container that exists but is not running has no
    // namespace to read — that is "not bound", reported as an empty table.
    `if [ -z "$files" ] && [ -z "$c" ]; then files="/proc/net/${base} /proc/net/${base}6"; fi`,
    `if [ -n "$files" ]; then say "NET_BEGIN"; cat $files 2>/dev/null; say "NET_END"; else say "NET_NONE"; fi`,
    `say "END"`,
  ].join("\n");
}

export type RuntimeProbe = {
  /** END marker seen — anything else means we learned nothing reliable */
  ok: boolean;
  unit: string | null;
  /** systemctl is-active verbatim (active|inactive|failed|activating|deactivating|reloading|unknown) */
  service: string | null;
  restarts: number | null;
  container: string | null;
  /** docker State.Status (running|exited|restarting|created|paused|dead) or null */
  containerState: string | null;
  containerHealth: string | null;
  startedAt: Date | null;
  /** the raw /proc/net table text (null = could not be read / no namespace) */
  netTable: string | null;
  /** NET_NONE: a container exists but has no running process to read */
  netAbsent: boolean;
};

/** Parse the probe's stdout. Never throws. */
export function parseRuntimeProbe(stdout: string): RuntimeProbe {
  const text = String(stdout ?? "");
  const one = (re: RegExp): string | null => {
    const m = re.exec(text);
    return m ? m[1].trim() : null;
  };
  const unitRaw = one(/^NXRT:UNIT:(.*)$/m);
  const ctrRaw = one(/^NXRT:CTR:(.*)$/m);
  const cstate = one(/^NXRT:CSTATE:(.*)$/m);
  let containerState: string | null = null;
  let containerHealth: string | null = null;
  let startedAt: Date | null = null;
  if (cstate && cstate !== "NONE") {
    const [status, started, health] = cstate.split("|");
    containerState = status?.trim() || null;
    containerHealth = health?.trim() || null;
    startedAt = parseDockerTime(started);
  }
  if (!startedAt) startedAt = parseSystemdTime(one(/^NXRT:SINCE:(.*)$/m));
  const nr = one(/^NXRT:NRESTARTS:(\d+)$/m);
  const b = text.indexOf("NXRT:NET_BEGIN");
  const e = text.indexOf("NXRT:NET_END");
  const netTable = b >= 0 && e > b ? text.slice(b + "NXRT:NET_BEGIN".length, e) : null;
  return {
    ok: /^NXRT:END$/m.test(text),
    unit: unitRaw && unitRaw !== "NONE" ? unitRaw : null,
    service: one(/^NXRT:SVC:(.*)$/m),
    restarts: nr === null ? null : Number(nr),
    container: ctrRaw && ctrRaw !== "NONE" ? ctrRaw : null,
    containerState,
    containerHealth,
    startedAt,
    netTable,
    netAbsent: /^NXRT:NET_NONE$/m.test(text),
  };
}

function parseDockerTime(s: string | undefined): Date | null {
  if (!s) return null;
  const t = s.trim();
  if (!t || t.startsWith("0001-01-01")) return null;
  const d = new Date(t);
  return Number.isFinite(d.getTime()) ? d : null;
}

/** `systemctl show -p ActiveEnterTimestamp` → "Thu 2026-10-01 04:23:20 UTC" (or empty). */
export function parseSystemdTime(s: string | null): Date | null {
  if (!s) return null;
  const m = /(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2}) UTC/.exec(s);
  if (!m) return null;
  const d = new Date(`${m[1]}T${m[2]}Z`);
  return Number.isFinite(d.getTime()) ? d : null;
}

// ---------------------------------------------------------------------------
// Classification
// ---------------------------------------------------------------------------

export type ClassifyInput = {
  probe: RuntimeProbe;
  /** procNetHasPort over probe.netTable, done by the I/O caller (null = could not tell) */
  portBound: boolean | null;
  /** TCP connect through the public path (null = not checked, e.g. UDP) */
  externalOk: boolean | null;
  intent: RunIntent | null;
  now: Date;
  startGraceMs?: number;
};

/** Turn one probe into one state. Pure; see the module header for the rules. */
export function classifyRuntime(input: ClassifyInput): GameRuntimeState {
  const { probe: p, portBound, externalOk, intent, now } = input;
  const grace = input.startGraceMs ?? START_GRACE_MS;
  if (!p.ok) return "unknown";
  if (!p.unit && !p.container) return "unknown";

  const svc = p.service ?? "unknown";
  const ctr = p.containerState;

  if (svc === "failed" || ctr === "restarting" || ctr === "dead") return "crashed";
  if (svc === "activating" || svc === "reloading") return "starting";
  if (svc === "inactive" || svc === "deactivating" || (svc !== "active" && ctr && ctr !== "running")) {
    return intent === "stopped" ? "stopped" : "game_stopped";
  }
  if (svc !== "active") return "unknown";

  // Unit active. A docker-wrapped unit can be "active" a moment before the
  // container is — or between crashes of a Restart=always loop.
  const inGrace = p.startedAt ? now.getTime() - p.startedAt.getTime() < grace : false;
  if (p.container && ctr !== "running") return inGrace ? "starting" : "crashed";
  if (p.containerHealth === "unhealthy") return "not_responding";

  if (portBound === true) return externalOk === false ? "not_responding" : "online";
  if (portBound === false) return inGrace ? "starting" : "not_responding";
  // Port table unreadable. A HEALTHCHECK that says healthy is real evidence.
  if (p.containerHealth === "healthy") return externalOk === false ? "not_responding" : "online";
  if (externalOk === true) return "online";
  return "unverified";
}

// ---------------------------------------------------------------------------
// The view the dashboards render
// ---------------------------------------------------------------------------

export type RuntimeTone = "ok" | "info" | "warn" | "bad" | "muted";

export type RuntimeRowLike = {
  state: string | null;
  probedAt: Date | string | null;
  probeOk?: boolean | null;
  probeError?: string | null;
  intent?: string | null;
  intentAt?: Date | string | null;
  intentSource?: string | null;
  startedAt?: Date | string | null;
  stateSince?: Date | string | null;
} | null;

export type RuntimeView = {
  state: GameRuntimeState;
  label: string;
  tone: RuntimeTone;
  /** one plain sentence for the customer, never empty */
  detail: string;
  /** ISO, or null when never probed */
  probedAt: string | null;
  /** the probe is older than RUNTIME_REFRESH_TTL_MS — ask for a fresh one */
  needsRefresh: boolean;
  /** the probe is too old to drive the badge — shown as unknown */
  stale: boolean;
  /** the game process is (believed) up — drives player/console polling */
  gameUp: boolean;
  canStart: boolean;
  canStop: boolean;
  canRestart: boolean;
};

const LABEL: Record<GameRuntimeState, { label: string; tone: RuntimeTone }> = {
  online: { label: "Online", tone: "ok" },
  unverified: { label: "Running", tone: "info" },
  starting: { label: "Starting", tone: "info" },
  not_responding: { label: "Not responding", tone: "warn" },
  stopped: { label: "Stopped", tone: "muted" },
  game_stopped: { label: "Game stopped", tone: "bad" },
  crashed: { label: "Crashed", tone: "bad" },
  unknown: { label: "Checking…", tone: "muted" },
};

export function runtimeLabel(state: GameRuntimeState): { label: string; tone: RuntimeTone } {
  return LABEL[state] ?? LABEL.unknown;
}

function toDate(v: Date | string | null | undefined): Date | null {
  if (!v) return null;
  const d = v instanceof Date ? v : new Date(v);
  return Number.isFinite(d.getTime()) ? d : null;
}

function isState(s: unknown): s is GameRuntimeState {
  return typeof s === "string" && (GAME_RUNTIME_STATES as readonly string[]).includes(s);
}

/** Power availability per state. Unknown → everything allowed: never hide Start on a guess. */
export function controlsFor(state: GameRuntimeState): { canStart: boolean; canStop: boolean; canRestart: boolean } {
  switch (state) {
    case "online":
    case "unverified":
    case "starting":
    case "not_responding":
      return { canStart: false, canStop: true, canRestart: true };
    case "stopped":
    case "game_stopped":
      return { canStart: true, canStop: false, canRestart: false };
    case "crashed":
    case "unknown":
    default:
      return { canStart: true, canStop: true, canRestart: true };
  }
}

function sourcePhrase(src: string | null | undefined): string {
  switch (src) {
    case "admin":
      return "by our support team";
    case "schedule":
      return "by a scheduled task";
    case "config":
      return "while applying settings";
    case "update":
      return "for an update";
    default:
      return "from your dashboard";
  }
}

/**
 * Everything the hero/badge needs, from the VM status + the cached runtime row.
 * Returns null when the VM itself is not RUNNING — the VM-level status
 * (Offline / Suspended / Deploying / Error) is then the whole truth.
 *
 * `legacyServiceState` is `gameConfig._serviceState` (written by GAME_POWER
 * since 2026-09-09). It is only consulted when there is no fresh probe, and
 * only ever to say "stopped" — never to claim "online".
 */
export function runtimeView(input: {
  vmStatus: string;
  row: RuntimeRowLike;
  now: Date;
  legacyServiceState?: unknown;
}): RuntimeView | null {
  if (input.vmStatus !== "RUNNING") return null;
  const row = input.row;
  const probedAt = toDate(row?.probedAt ?? null);
  const age = probedAt ? input.now.getTime() - probedAt.getTime() : Infinity;
  const stale = age > RUNTIME_STALE_MS;
  const needsRefresh = age > RUNTIME_REFRESH_TTL_MS;
  const intent = row?.intent === "stopped" || row?.intent === "running" ? (row.intent as RunIntent) : null;

  let state: GameRuntimeState = "unknown";
  if (!stale && isState(row?.state)) state = row!.state as GameRuntimeState;
  else if (input.legacyServiceState === "inactive") state = intent === "running" ? "game_stopped" : "stopped";
  else if (input.legacyServiceState === "failed") state = "crashed";

  const { label, tone } = runtimeLabel(state);
  const intentAt = toDate(row?.intentAt ?? null);
  let detail: string;
  switch (state) {
    case "online":
      detail = "The game is running and accepting connections.";
      break;
    case "unverified":
      detail = "The game service is running, but we couldn't confirm its port yet.";
      break;
    case "starting":
      detail = "The game is starting up — players can join once it finishes loading.";
      break;
    case "not_responding":
      detail = "The game service is running, but it isn't accepting connections. A restart usually fixes this.";
      break;
    case "stopped":
      detail = `The game was stopped ${sourcePhrase(row?.intentSource)}${intentAt ? ` on ${intentAt.toISOString().slice(0, 16).replace("T", " ")} UTC` : ""}. Press Start to bring it back.`;
      break;
    case "game_stopped":
      detail = "The game isn't running, and nobody asked for it to stop. Press Start to bring it back.";
      break;
    case "crashed":
      detail = "The game process has crashed. Start or Restart it, and check Console → Logs if it happens again.";
      break;
    default:
      detail = row?.probeError
        ? "We couldn't check the game just now. Power controls stay available."
        : "Checking the game's status…";
  }
  return {
    state,
    label,
    tone,
    detail,
    probedAt: probedAt ? probedAt.toISOString() : null,
    needsRefresh,
    stale,
    gameUp: GAME_UP_STATES.has(state) || state === "unknown",
    ...controlsFor(state),
  };
}

// ---------------------------------------------------------------------------
// Where to check the game from OUTSIDE
// ---------------------------------------------------------------------------

export type CheckTarget = { host: string; port: number; path: "dedicated" | "forward" };

/**
 * The address a player actually uses to reach `game.port`, as seen from the
 * worker on the primary.
 *
 * ROOT CAUSE of most GAME_POWER "start/restart reported active but port never
 * bound" failures (17 Minecraft restarts in 14 days, plus Rust/Terraria/
 * Valheim): GAME_POWER and GAME_REINSTALL probed `node.publicIp:game.port`,
 * i.e. 54.39.132.159:25565 — a port the NODE does not forward at all. NAT game
 * servers are published on an allocated public port (PortForward.publicPort,
 * 20000-29999). TCP families therefore timed out every time, a healthy start
 * was reported to the customer as a failure, and the job was retried — each
 * retry restarting the game again. UDP families "passed" only because silence
 * counts as success for UDP. PROVISION already got this right on non-primary
 * nodes; this is that logic, shared.
 *
 * Returns null when no public path exists for that port (no forward) — the
 * caller then relies on the in-guest binding check alone, which is honest.
 * The primary routes its own public IP back through NXEON_FWD (an OUTPUT-chain
 * DNAT rule), so the forward path is valid for primary-node servers too.
 */
export function gameCheckTarget(
  server: {
    dedicatedIp?: { address: string } | null;
    node?: { publicIp: string | null } | null;
    portForwards?: { publicPort: number; guestPort: number; protocol: string }[] | null;
  },
  game: { port: number; protocol: "tcp" | "udp" },
  fallbackPublicIp?: string | null
): CheckTarget | null {
  if (server.dedicatedIp?.address) return { host: server.dedicatedIp.address, port: game.port, path: "dedicated" };
  const fwd = (server.portForwards ?? []).find(
    (f) => f.guestPort === game.port && (f.protocol || "tcp").toLowerCase() === game.protocol
  );
  const host = server.node?.publicIp ?? fallbackPublicIp ?? null;
  if (fwd && host) return { host, port: fwd.publicPort, path: "forward" };
  return null;
}

// ---------------------------------------------------------------------------
// Fleet sweep decisions
// ---------------------------------------------------------------------------

/** "VM up, game down, not intentionally stopped" for longer than this → admin alert. */
export const GAME_DOWN_ALERT_MS = Number(process.env.GAME_DOWN_ALERT_MIN ?? 10) * 60_000;
/** Never auto-restart the same server more often than this. */
export const AUTO_RESTART_COOLDOWN_MS = 60 * 60_000;

export type SweepDecision = {
  /** new downSince to persist (null = clear) */
  downSince: Date | null;
  /** clear alertedAt (the down spell ended) */
  clearAlert: boolean;
  alert: boolean;
  autoRestart: boolean;
};

/**
 * What the sweep should do after classifying one server. Pure.
 *
 * Alerts once per down spell (alertedAt is set by the caller and cleared when
 * the game is back up or intentionally stopped). Auto-restart is only ever
 * considered when enabled (per-server flag or global env, BOTH default OFF),
 * only for a down spell that has already outlived the alert threshold, never
 * for an intentional stop, and at most once per cooldown.
 */
export function sweepDecision(input: {
  state: GameRuntimeState;
  intent: RunIntent | null;
  downSince: Date | null;
  alertedAt: Date | null;
  lastAutoRestartAt: Date | null;
  autoRestartEnabled: boolean;
  now: Date;
  alertAfterMs?: number;
}): SweepDecision {
  const after = input.alertAfterMs ?? GAME_DOWN_ALERT_MS;
  const down = GAME_DOWN_STATES.has(input.state) && input.intent !== "stopped";
  if (!down) {
    // "unknown" neither starts nor ends a spell — one failed probe proves nothing.
    if (input.state === "unknown") {
      return { downSince: input.downSince, clearAlert: false, alert: false, autoRestart: false };
    }
    return { downSince: null, clearAlert: !!input.alertedAt, alert: false, autoRestart: false };
  }
  const since = input.downSince ?? input.now;
  const long = input.now.getTime() - since.getTime() >= after;
  const alert = long && !input.alertedAt;
  const cooled =
    !input.lastAutoRestartAt || input.now.getTime() - input.lastAutoRestartAt.getTime() >= AUTO_RESTART_COOLDOWN_MS;
  return { downSince: since, clearAlert: false, alert, autoRestart: long && input.autoRestartEnabled && cooled };
}

// ---------------------------------------------------------------------------
// GAME_CONFIG run-state semantics
// ---------------------------------------------------------------------------

export type ConfigApplyPlan =
  /** do nothing to the run state */
  | { action: "none"; note: string | null }
  /** the apply started a server that was stopped — stop it again */
  | { action: "restore-stop"; note: string }
  /** restart now to apply */
  | { action: "restart"; note: string }
  /** the apply left a running server down — bring it back */
  | { action: "recover-start"; note: string };

/**
 * After a settings apply, what (if anything) must happen to the game's run
 * state so the customer is never left worse off than before, and never left
 * guessing. Pure: the worker probes before/after and acts on this.
 *
 *  - wasRunning + now down          → recover-start (never silently leave it down)
 *  - was stopped + apply started it → restore-stop  (respect the stop)
 *  - was stopped                    → none, and SAY that it stays stopped
 *  - wasRunning + not restarted + changes + restart asked → restart
 *  - wasRunning + not restarted + changes, no restart asked → none, say a restart is needed
 */
export function planAfterConfigApply(input: {
  wasRunning: boolean | null;
  isRunning: boolean | null;
  restartedDuringApply: boolean;
  restartRequested: boolean;
  hasChanges: boolean;
  liveApplied: boolean;
}): ConfigApplyPlan {
  const { wasRunning, isRunning } = input;
  if (wasRunning === true && isRunning === false) {
    return {
      action: "recover-start",
      note: "Your server was running before this change and wasn't afterwards, so we started it again.",
    };
  }
  if (wasRunning === false) {
    if (isRunning === true) {
      return {
        action: "restore-stop",
        note: "Your server was stopped before this change, so we left it stopped. The new settings take effect when you start it.",
      };
    }
    return {
      action: "none",
      note: "Your server is stopped, so we left it stopped. The new settings take effect when you start it.",
    };
  }
  if (wasRunning === null) {
    return { action: "none", note: "We couldn't check whether your server was running, so we didn't restart it." };
  }
  // wasRunning === true and still running
  if (input.restartedDuringApply || !input.hasChanges || input.liveApplied) return { action: "none", note: null };
  if (input.restartRequested) return { action: "restart", note: "Restarted your server to apply the new settings." };
  return {
    action: "none",
    note: "Saved. These settings take effect after a restart — use “Apply & restart”, or restart from the power controls when it suits you.",
  };
}

