/**
 * AUDIT (2026-10-01) of what GAME_UPDATE did for each family before this:
 * STEAM_APPID above is EMPTY for the whole catalog, so for EVERY family the job
 * resolved the unit, reported its state, and changed nothing — it never
 * downloaded anything and never restarted. "Automatic updates: on" was, in
 * practice, a 6-hourly health check. Meanwhile the two families whose image
 * really can move versions (itzg Minecraft Java + Bedrock) only do so through
 * their VERSION env var, which the platform pins on purpose (VERSION drift
 * broke a Cobblemon server on 2026-09-06).
 *
 * So the plan below is the only real update path that exists today:
 *  - "bump": a PINNED VERSION on a family whose real-apply path already knows
 *    how to recreate the container on a new VERSION (worker/game-config.ts
 *    applyMinecraft / applyBedrock), moving to the newest version in the
 *    platform's own curated list (lib/game-config.ts) — never a version the
 *    platform has not vetted (Java-image mapping included). Minecraft only for
 *    the VANILLA server type: Paper/Purpur/Fabric/Forge pin a version their
 *    plugins/mods depend on, and moving it is exactly the breakage auto-update
 *    must not cause.
 *  - "follows-latest": VERSION=LATEST already updates on every restart; the
 *    toggle cannot change that and the copy says so.
 *  - "none": no update source on this platform. The job is a health check.
 */
export type AutoUpdatePlan =
  | { kind: "bump"; from: string; to: string }
  | { kind: "current"; version: string }
  | { kind: "follows-latest" }
  | { kind: "none"; reason: string };

/** Compare dotted numeric versions ("1.21.11" vs "26.2"). Non-numeric parts sort as 0. */
export function compareVersions(a: string, b: string): number {
  const pa = a.split(".").map((x) => Number.parseInt(x, 10) || 0);
  const pb = b.split(".").map((x) => Number.parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (d !== 0) return d < 0 ? -1 : 1;
  }
  return 0;
}

/** Families with a real version-bump path, and the variants it may run on (null = any). */
export const VERSION_BUMP_FAMILIES: Record<string, { variants: string[] | null; label: string }> = {
  minecraft: { variants: ["vanilla"], label: "Minecraft" },
  bedrock: { variants: null, label: "Minecraft Bedrock" },
};

/**
 * Pure: given the family, server type and saved config, and the curated
 * version list for that family (newest first, real versions only — caller
 * strips LATEST/PREVIEW), what would an auto-update do?
 */
export function autoUpdatePlan(input: {
  family: string;
  variant: string | null;
  config: Record<string, unknown> | null;
  curated: string[];
}): AutoUpdatePlan {
  const bump = VERSION_BUMP_FAMILIES[input.family];
  if (!bump) {
    return { kind: "none", reason: "no-source" };
  }
  const variant = input.variant ?? (input.family === "minecraft" ? "vanilla" : null);
  if (bump.variants && (!variant || !bump.variants.includes(variant))) {
    return { kind: "none", reason: "pinned-for-mods" };
  }
  const current = input.config?.["VERSION"];
  if (current === "LATEST" || current === "PREVIEW") return { kind: "follows-latest" };
  if (typeof current !== "string" || !current) return { kind: "none", reason: "no-version" };
  const newest = input.curated.find((v) => /^\d+(\.\d+)*$/.test(v));
  if (!newest) return { kind: "current", version: current };
  return compareVersions(newest, current) > 0
    ? { kind: "bump", from: current, to: newest }
    : { kind: "current", version: current };
}

/** Honest one-paragraph copy for the auto-update toggle, per plan. */
export function autoUpdateCopy(plan: AutoUpdatePlan, gameName: string, variantLabel?: string | null): string {
  switch (plan.kind) {
    case "bump":
    case "current":
      return (
        `When on, every 6 hours we check for a newer ${gameName} version that Nxeon supports. If there is one, ` +
        `we back up your world first, switch your server to it, restart, check that it really came back online, ` +
        `and tell you exactly what changed. If it doesn't come back, we put the previous version back.`
      );
    case "follows-latest":
      return (
        `Your server is set to “Always latest”, so ${gameName} already updates itself every time it restarts — ` +
        `this switch can't change that. Pick a fixed version in Game settings if you'd rather choose when to update.`
      );
    case "none":
      if (plan.reason === "pinned-for-mods") {
        return (
          `${variantLabel ?? "Modded"} servers stay on the ${gameName} version your plugins or mods are built for, ` +
          `so we never change it automatically. With this on we only check every 6 hours that your server is ` +
          `running — nothing is downloaded and nothing restarts. Change the version yourself in Game settings.`
        );
      }
      return (
        `${gameName} has no automatic update source on Nxeon yet. With this on we only check every 6 hours that ` +
        `your server is running — nothing is downloaded and nothing restarts. To update, upload new server files ` +
        `in the Files tab, or reinstall the game.`
      );
  }
}
