  const label = `${target.host}:${target.port}`;
  // UDP has no handshake: silence is not evidence (see provision-health's
  // udpAttempt). The in-guest binding is the UDP truth, not this.
  if (game.protocol !== "tcp") return { ok: null, target: label };
  const r = await checkGamePortOpen(target.host, target.port, "tcp", { timeoutMs: 0, intervalMs: 1 });
  return { ok: r.ok, target: label, error: r.ok ? undefined : r.error };
}

/**
 * Probe one game server. Never throws: an SSH failure is a result
 * (state "unknown" + error), not an exception — a probe that cannot reach
 * the guest must never be mistaken for evidence the game is down, nor up.
 */
export async function probeGameRuntime(
  server: RuntimeServer,
  opts?: { external?: boolean; now?: Date }
): Promise<RuntimeProbeResult | null> {
  const family = familyOf(server);
  if (!family) return null;
  const spec = controlSpec(family);
  const game = GAME_PORT[family];
  const intent = (server.gameRuntime?.intent as RunIntent | null) ?? null;
  const now = opts?.now ?? new Date();
  if (!spec || !game) return null;

  if (SANDBOX) {
    // No VM exists. Report what the owner last asked for and say it is simulated.
    const state: GameRuntimeState = intent === "stopped" ? "stopped" : "online";
    return {
      family,
      probe: { ...emptyProbe(), ok: true, unit: `${spec.serviceHints[0]}.service`, service: intent === "stopped" ? "inactive" : "active" },
      portBound: intent === "stopped" ? false : true,
      externalOk: null,
      externalTarget: null,
      state,
      error: "sandbox: simulated, no VM contacted",
    };
  }
  if (server.status !== "RUNNING") {
    return { family, probe: emptyProbe(), portBound: null, externalOk: null, externalTarget: null, state: "unknown", error: "VM is not running" };
  }

  let probe = emptyProbe();
  let error: string | null = null;
  try {
    const script = runtimeProbeScript({ hints: spec.serviceHints, family, protocol: game.protocol });
    const r = await withServerSsh(server as SftpServer, (conn) => exec(conn, script, QUICK_TIMEOUT_MS));
    probe = parseRuntimeProbe(r.stdout);
    if (!probe.ok) error = "probe did not complete";
  } catch (e) {
    error = String((e as Error)?.message ?? e).slice(0, 300);
  }

  let portBound: boolean | null = null;
  if (probe.ok) {
    if (probe.netTable !== null) portBound = procNetHasPort(probe.netTable, game.port, { tcpListeningOnly: game.protocol === "tcp" });
    else if (probe.netAbsent) portBound = false;
  }

  let externalOk: boolean | null = null;
  let externalTarget: string | null = null;
  // Only worth asking the outside world when the inside says the game is listening.
  if (opts?.external !== false && portBound === true) {
    const ext = await externalTcpCheck(server, game).catch(() => ({ ok: null, target: null }));
    externalOk = ext.ok;
    externalTarget = ext.target;
  }

  const state = classifyRuntime({ probe, portBound, externalOk, intent, now });
  return { family, probe, portBound, externalOk, externalTarget, state, error };
}

/** Persist a probe result into the GameRuntime cache (upsert). Never throws. */
export async function saveRuntime(serverId: string, r: RuntimeProbeResult, now = new Date()): Promise<void> {
  try {
    const prev = await db.gameRuntime.findUnique({ where: { serverId }, select: { state: true } });
    const data = {
      probedAt: now,
      probeOk: r.probe.ok,
      probeError: r.error,
      unit: r.probe.unit,
      serviceState: r.probe.service,
      containerState: r.probe.containerState,
      containerHealth: r.probe.containerHealth,
      startedAt: r.probe.startedAt,
      restarts: r.probe.restarts,
      portBound: r.portBound,
      externalOk: r.externalOk,
      externalTarget: r.externalTarget,
      state: r.state,
      ...(prev?.state !== r.state ? { stateSince: now } : {}),
    };
    await db.gameRuntime.upsert({
      where: { serverId },
      create: { serverId, ...data, stateSince: now },
      update: data,
    });
  } catch (e) {
    console.error(`[game-runtime] could not save runtime for ${serverId}`, e);
  }
}

/** Probe + save in one go. Returns the result (or null for a non-game server). */
export async function refreshRuntime(serverId: string, opts?: { external?: boolean }): Promise<RuntimeProbeResult | null> {
  const server = (await db.server.findUnique({ where: { id: serverId }, select: RUNTIME_SERVER_SELECT })) as RuntimeServer | null;
  if (!server) return null;
  const r = await probeGameRuntime(server, opts);
  if (r && !(SANDBOX && server.gameRuntime?.state)) await saveRuntime(server.id, r);
  return r;
}

/**
 * Record what the owner/admin ASKED for. This is what separates "stopped by
 * choice" from "crashed / stopped by something else" — a crash is never
 * written here, only an explicit action is. Never throws.
 */
export async function recordIntent(
  serverId: string,
  intent: RunIntent,
  source: IntentSource,
  userId: string | null
): Promise<void> {
  const now = new Date();
  try {
    await db.gameRuntime.upsert({
      where: { serverId },
      create: { serverId, intent, intentAt: now, intentBy: userId, intentSource: source },
      update: {
        intent,
        intentAt: now,
        intentBy: userId,
        intentSource: source,
        // An explicit action ends any "unexplained down" spell.
        downSince: null,
        alertedAt: null,
      },
    });
  } catch (e) {
    console.error(`[game-runtime] could not record intent for ${serverId}`, e);
  }
}

