import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "../lib/ssh-exec";
import type { SftpServer } from "../lib/sftp";
import { controlSpec, runRcon, shq, GAME_BACKUP_DIR } from "../lib/game-control";
import { GAME_PORT, joinPortsFor } from "../lib/games";
import { schemaFor, validateConfig } from "../lib/game-config";
import { sweepDecision, runtimeLabel, type RunIntent } from "../lib/game-runtime";
import {
  RUNTIME_SERVER_SELECT,
  familyOf,
  probeGameRuntime,
  saveRuntime,
  externalTcpCheck,
  type RuntimeServer,
} from "../lib/game-runtime-probe";
import { notifyAdmins } from "./monitor";

/**
 * Game runtime — worker side: the fleet sweep and the post-provision
 * readiness checklist. See lib/game-runtime.ts for the rules and the
 * 2026-09-30 incident that motivated all of it.
 *
 * Wire-up (worker/index.ts):
 *   - `gameRuntimeSweepTick()` from the main loop — it is NON-BLOCKING: it
 *     starts a sweep in the background if one is due and none is running, and
 *     returns immediately. (The incident's GAME_CONFIG job sat QUEUED ~6 min
 *     behind inline sweeps; this must never add to that.)
 *   - `runProvisionReadiness(...)` at the end of a game PROVISION.
 */

const SWEEP_EVERY_MS = Number(process.env.GAME_RUNTIME_SWEEP_SEC ?? 120) * 1000;
const SWEEP_CONCURRENCY = 4;
/** Global auto-restart switch — default OFF. Per-server GameRuntime.autoRestart also enables it. */
const GLOBAL_AUTO_RESTART = process.env.GAME_AUTO_RESTART === "1";

let sweepRunning = false;
let lastSweepAt = 0;

/** Call every loop iteration; never awaits the sweep itself. */
export function gameRuntimeSweepTick(): void {
  if (SANDBOX || sweepRunning || Date.now() - lastSweepAt < SWEEP_EVERY_MS) return;
  sweepRunning = true;
  lastSweepAt = Date.now();
  gameRuntimeSweep()
    .catch((e) => console.error("[game-runtime] sweep failed", e))
    .finally(() => {
      sweepRunning = false;
    });
}

async function mapLimit<T>(items: T[], limit: number, fn: (t: T) => Promise<void>): Promise<void> {
  let i = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) {
      const item = items[i++];
      await fn(item).catch((e) => console.error("[game-runtime] item failed", e));
    }
  });
  await Promise.all(workers);
}

/**
 * Probe every RUNNING game server, cache the result, and flag "VM up, game
 * down, not intentionally stopped" spells that outlive GAME_DOWN_ALERT_MIN to
 * the admins — once per spell. Auto-restart only when enabled (per-server flag
 * or GAME_AUTO_RESTART=1; both default OFF), at most once per hour per server.
 * Skips servers with a job in flight (their state is changing under us).
 */
export async function gameRuntimeSweep(): Promise<void> {
  const servers = (await db.server.findMany({
    where: { status: "RUNNING", OR: [{ gamePlanId: { not: null } }, { osTemplate: { category: "GAME" } }] },
    select: RUNTIME_SERVER_SELECT,
  }).catch(async () =>
    // `category` may not be a GAME enum on every schema revision — fall back to plans only.
    db.server.findMany({ where: { status: "RUNNING", gamePlanId: { not: null } }, select: RUNTIME_SERVER_SELECT })
  )) as unknown as RuntimeServer[];

  const candidates = servers.filter((s) => familyOf(s));
  if (candidates.length === 0) return;
  const busyRows = await db.job.findMany({
    where: { serverId: { in: candidates.map((s) => s.id) }, status: { in: ["QUEUED", "RUNNING"] } },
    select: { serverId: true },
  });
  const busy = new Set(busyRows.map((b) => b.serverId));

  let down = 0;
  await mapLimit(candidates, SWEEP_CONCURRENCY, async (server) => {
    if (busy.has(server.id)) return;
    const now = new Date();
    const r = await probeGameRuntime(server, { now });
    if (!r) return;
    await saveRuntime(server.id, r, now);

    const row = await db.gameRuntime.findUnique({
      where: { serverId: server.id },
      select: { intent: true, downSince: true, alertedAt: true, lastAutoRestartAt: true, autoRestart: true },
    });
    const d = sweepDecision({
      state: r.state,
      intent: (row?.intent as RunIntent | null) ?? null,
      downSince: row?.downSince ?? null,
      alertedAt: row?.alertedAt ?? null,
      lastAutoRestartAt: row?.lastAutoRestartAt ?? null,
      autoRestartEnabled: GLOBAL_AUTO_RESTART || !!row?.autoRestart,
      now,
    });
    if (d.downSince) down++;
    await db.gameRuntime.update({
      where: { serverId: server.id },
      data: {
        downSince: d.downSince,
        ...(d.clearAlert ? { alertedAt: null } : {}),
        ...(d.alert ? { alertedAt: now } : {}),
        ...(d.autoRestart ? { lastAutoRestartAt: now } : {}),
      },
    });

    if (d.alert) {
      const mins = Math.round((now.getTime() - (d.downSince ?? now).getTime()) / 60_000);
      const label = runtimeLabel(r.state).label;
      await notifyAdmins(
        `Game down: ${server.hostname} (${label}) for ${mins}+ min`,
        `${server.hostname} (${r.family}, ${server.node?.name ?? "?"}) — VM is running but the game is "${label}" ` +
          `and nobody stopped it on purpose. service=${r.probe.service ?? "?"} container=${r.probe.containerState ?? "?"} ` +
          `portBound=${String(r.portBound)} external=${String(r.externalOk)}${r.externalTarget ? ` (${r.externalTarget})` : ""}` +
          `${r.error ? ` probeError=${r.error}` : ""}. ` +
          (GLOBAL_AUTO_RESTART || row?.autoRestart ? "Auto-restart is ON for this server." : "Auto-restart is off (alert only)."),
        `/admin/servers/${server.id}`
      ).catch((e) => console.error("[game-runtime] admin alert failed", e));
      await db.auditLog
        .create({ data: { userId: null, action: "gameserver.runtime.down_alert", detail: `${server.hostname} state=${r.state} for ${mins}m` } })
        .catch(() => {});
    }
    if (d.autoRestart) {
      const inflight = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
      if (inflight === 0) {
        const action = r.state === "game_stopped" ? "start" : "restart";
        await db.job.create({
          data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: false, source: "auto-restart" } },
        });
        await db.auditLog
          .create({ data: { userId: null, action: "gameserver.runtime.auto_restart", detail: `${server.hostname} ${action} (state=${r.state})` } })
          .catch(() => {});
      }
    }
  });
  if (down > 0) console.log(`[game-runtime] sweep: ${candidates.length} game server(s) probed, ${down} down without a stop on record`);
}

// ---------------------------------------------------------------------------
// Post-provision readiness checklist
// ---------------------------------------------------------------------------

export type ReadinessStatus = "pass" | "fail" | "warn" | "skip";
export type ReadinessCheck = { id: string; label: string; status: ReadinessStatus; detail: string };

/**
 * Run the readiness checklist for a freshly provisioned game server and record
 * it on its GameRuntime row. Never throws; returns the result so provision()
 * can tell the customer "up, with caveats" instead of "ready".
 *
 * Checks (each one a thing a real incident got past):
 *  1. service       — the game's systemd unit is active (and not crash-looping)
 *  2. port_local    — the game port is bound inside the game's own namespace
 *  3. forwards      — every join port has a public forward (NAT servers)
 *  4. external      — a TCP connect to the PUBLIC ip:port from the primary
 *                     (a vantage outside the guest and outside its node);
 *                     UDP is reported as "skip" with the reason, never "pass"
 *  5. config        — saved settings validate against the family schema
 *  6. data_dir      — the world/save directory exists
 *  7. backup_dir    — the platform's backup dir is creatable + writable
 *  8. rcon          — the remote console answers (families that have one)
 *
 * readinessOk = no "fail". Fails alert the admins (the provision still
 * completes — the VM is real and paid for; it is marked as needing attention).
 */
export async function runProvisionReadiness(serverId: string): Promise<{ ok: boolean; checks: ReadinessCheck[] } | null> {
  if (SANDBOX) return null;
  try {
    const server = (await db.server.findUnique({
      where: { id: serverId },
      select: { ...RUNTIME_SERVER_SELECT, gameConfig: true, gameVariant: true },
    })) as (RuntimeServer & { gameConfig: unknown; gameVariant: string | null }) | null;
    if (!server) return null;
    const family = familyOf(server);
    if (!family) return null;
    const spec = controlSpec(family);
    const game = GAME_PORT[family];
    const checks: ReadinessCheck[] = [];
    const now = new Date();

    const r = await probeGameRuntime(server, { external: false, now });
    if (r) await saveRuntime(server.id, r, now);
    const svc = r?.probe.service ?? null;
    checks.push({
      id: "service",
      label: "Game service running",
      status: svc === "active" && r?.state !== "crashed" ? "pass" : "fail",
      detail: r?.probe.ok
        ? `unit ${r.probe.unit ?? "?"} is ${svc ?? "?"}${r.probe.containerState ? `, container ${r.probe.containerState}` : ""}${r.probe.restarts ? `, ${r.probe.restarts} restart(s)` : ""}`
        : `could not probe the guest: ${r?.error ?? "no result"}`,
    });
    checks.push({
      id: "port_local",
      label: `Game port ${game.port}/${game.protocol} bound inside the server`,
      status: r?.portBound === true ? "pass" : r?.portBound === false ? "fail" : "warn",
      detail: r?.portBound === true ? "bound in the game's own network namespace" : r?.portBound === false ? "nothing is bound to it" : "could not read the guest's socket table",
    });

    if (!server.dedicatedIp) {
      const missing = joinPortsFor(family).filter(
        (jp) => !(server.portForwards ?? []).some((f) => f.guestPort === jp.port && f.protocol === jp.protocol)
      );
      checks.push({
        id: "forwards",
        label: "Join ports published",
        status: missing.length === 0 ? "pass" : "fail",
        detail: missing.length === 0 ? "every join port has a public forward" : `no public forward for ${missing.map((m) => `${m.port}/${m.protocol}`).join(", ")}`,
      });
    }

    const ext = await externalTcpCheck(server, game).catch((e) => ({ ok: null, target: null, error: String(e) }));
    checks.push({
      id: "external",
      label: "Reachable from the internet",
      status: ext.ok === true ? "pass" : ext.ok === false ? "fail" : "skip",
      detail:
        ext.ok === true
          ? `TCP connect to ${ext.target} from the platform's primary succeeded`
          : ext.ok === false
            ? `TCP connect to ${ext.target} from the primary failed: ${(ext as { error?: string }).error ?? "no answer"}`
            : game.protocol === "udp"
              ? `UDP has no handshake, so an outside probe cannot prove anything${ext.target ? ` (${ext.target})` : ""}; relying on the in-server binding check`
              : `no public path for ${game.port}/${game.protocol} to check (no forward) — the join-port check covers what players use`,
    });

    if (schemaFor(family)) {
      const v = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
      checks.push({ id: "config", label: "Saved settings valid", status: v.ok ? "pass" : "fail", detail: v.ok ? "settings validate against the game's schema" : v.error });
    }

    if (spec) {
      try {
        await withServerSsh(server as SftpServer, async (conn) => {
          const dirs = spec.dataRoots.map((d) => shq(d)).join(" ");
          const out = await exec(
            conn,
            `found=""; for d in ${dirs}; do [ -d "$d" ] && { found="$d"; break; }; done; echo "NXRD:DATA:$found"; ` +
              `mkdir -p ${shq(GAME_BACKUP_DIR)} 2>/dev/null && [ -w ${shq(GAME_BACKUP_DIR)} ] && echo NXRD:BACKUP:ok || echo NXRD:BACKUP:no`,
            QUICK_TIMEOUT_MS
          );
          const data = /NXRD:DATA:(.*)/.exec(out.stdout)?.[1]?.trim() ?? "";
          checks.push({ id: "data_dir", label: "World/save directory present", status: data ? "pass" : "warn", detail: data ? data : `none of ${spec.dataRoots.join(", ")} exists yet` });
          const bk = /NXRD:BACKUP:ok/.test(out.stdout);
          checks.push({ id: "backup_dir", label: "Backup directory writable", status: bk ? "pass" : "warn", detail: bk ? GAME_BACKUP_DIR : `${GAME_BACKUP_DIR} could not be created/written` });
          if (spec.rcon === "source") {
            const rc = await runRcon(conn, spec, spec.listCommand ?? "help").catch((e) => ({ ok: false as const, error: String(e) }));
            checks.push({
              id: "rcon",
              label: "Remote console answers",
              status: rc.ok ? "pass" : "warn",
              detail: rc.ok ? "RCON authenticated and answered" : `RCON did not answer: ${(rc as { error?: string }).error ?? "?"}`,
            });
          }
        });
      } catch (e) {
        checks.push({ id: "data_dir", label: "World/save directory present", status: "warn", detail: `could not check: ${String((e as Error)?.message ?? e).slice(0, 160)}` });
      }
    }

    const ok = !checks.some((c) => c.status === "fail");
    await db.gameRuntime.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, readiness: checks as any, readinessAt: now, readinessOk: ok, intent: "running", intentAt: now, intentSource: "provision" },
      update: { readiness: checks as any, readinessAt: now, readinessOk: ok },
    });
    await db.auditLog
      .create({
        data: {
          userId: null,
          action: ok ? "gameserver.readiness.pass" : "gameserver.readiness.fail",
          detail: `${server.hostname}: ${checks.map((c) => `${c.id}=${c.status}`).join(" ")}`,
        },
      })
      .catch(() => {});
    if (!ok) {
      const failed = checks.filter((c) => c.status === "fail");
      await notifyAdmins(
        `Provision needs attention: ${server.hostname}`,
        `${server.hostname} (${family}) finished provisioning but failed its readiness checklist: ` +
          failed.map((c) => `${c.label} — ${c.detail}`).join("; "),
        `/admin/servers/${server.id}`
      ).catch(() => {});
    }
    return { ok, checks };
  } catch (e) {
    console.error(`[game-runtime] readiness for ${serverId} failed`, e);
    return null;
  }
}

