// ---------------------------------------------------------------------------
// Post-provision readiness checklist
// ---------------------------------------------------------------------------

export type ReadinessStatus = "pass" | "fail" | "warn" | "skip";
export type ReadinessCheck = { id: string; label: string; status: ReadinessStatus; detail: string };

/**
 * Run the readiness checklist for a freshly provisioned game server and record
 * it on its GameRuntime row. Never throws; returns the result so provision()
 * can tell the customer "up, with caveats" instead of "ready".
 *
 * Checks (each one a thing a real incident got past):
 *  1. service       — the game's systemd unit is active (and not crash-looping)
 *  2. port_local    — the game port is bound inside the game's own namespace
 *  3. forwards      — every join port has a public forward (NAT servers)
 *  4. external      — a TCP connect to the PUBLIC ip:port from the primary
 *                     (a vantage outside the guest and outside its node);
 *                     UDP is reported as "skip" with the reason, never "pass"
 *  5. config        — saved settings validate against the family schema
 *  6. data_dir      — the world/save directory exists
 *  7. backup_dir    — the platform's backup dir is creatable + writable
 *  8. rcon          — the remote console answers (families that have one)
 *
 * readinessOk = no "fail". Fails alert the admins (the provision still
 * completes — the VM is real and paid for; it is marked as needing attention).
 */
export async function runProvisionReadiness(serverId: string): Promise<{ ok: boolean; checks: ReadinessCheck[] } | null> {
  if (SANDBOX) return null;
  try {
    const server = (await db.server.findUnique({
      where: { id: serverId },
      select: { ...RUNTIME_SERVER_SELECT, gameConfig: true, gameVariant: true },
    })) as (RuntimeServer & { gameConfig: unknown; gameVariant: string | null }) | null;
    if (!server) return null;
    const family = familyOf(server);
    if (!family) return null;
    const spec = controlSpec(family);
    const game = GAME_PORT[family];
    const checks: ReadinessCheck[] = [];
    const now = new Date();

    const r = await probeGameRuntime(server, { external: false, now });
    if (r) await saveRuntime(server.id, r, now);
    const svc = r?.probe.service ?? null;
    checks.push({
      id: "service",
      label: "Game service running",
      status: svc === "active" && r?.state !== "crashed" ? "pass" : "fail",
      detail: r?.probe.ok
        ? `unit ${r.probe.unit ?? "?"} is ${svc ?? "?"}${r.probe.containerState ? `, container ${r.probe.containerState}` : ""}${r.probe.restarts ? `, ${r.probe.restarts} restart(s)` : ""}`
        : `could not probe the guest: ${r?.error ?? "no result"}`,
    });
    checks.push({
      id: "port_local",
      label: `Game port ${game.port}/${game.protocol} bound inside the server`,
      status: r?.portBound === true ? "pass" : r?.portBound === false ? "fail" : "warn",
      detail: r?.portBound === true ? "bound in the game's own network namespace" : r?.portBound === false ? "nothing is bound to it" : "could not read the guest's socket table",
    });

    if (!server.dedicatedIp) {
      const missing = joinPortsFor(family).filter(
        (jp) => !(server.portForwards ?? []).some((f) => f.guestPort === jp.port && f.protocol === jp.protocol)
      );
      checks.push({
        id: "forwards",
        label: "Join ports published",
        status: missing.length === 0 ? "pass" : "fail",
        detail: missing.length === 0 ? "every join port has a public forward" : `no public forward for ${missing.map((m) => `${m.port}/${m.protocol}`).join(", ")}`,
      });
    }

    const ext = await externalTcpCheck(server, game).catch((e) => ({ ok: null, target: null, error: String(e) }));
    checks.push({
      id: "external",
      label: "Reachable from the internet",
      status: ext.ok === true ? "pass" : ext.ok === false ? "fail" : "skip",
      detail:
        ext.ok === true
          ? `TCP connect to ${ext.target} from the platform's primary succeeded`
          : ext.ok === false
            ? `TCP connect to ${ext.target} from the primary failed: ${(ext as { error?: string }).error ?? "no answer"}`
            : game.protocol === "udp"
              ? `UDP has no handshake, so an outside probe cannot prove anything${ext.target ? ` (${ext.target})` : ""}; relying on the in-server binding check`
              : `no public path for ${game.port}/${game.protocol} to check (no forward) — the join-port check covers what players use`,
    });

    if (schemaFor(family)) {
      const v = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
      checks.push({ id: "config", label: "Saved settings valid", status: v.ok ? "pass" : "fail", detail: v.ok ? "settings validate against the game's schema" : v.error });
    }

    if (spec) {
      try {
        await withServerSsh(server as SftpServer, async (conn) => {
          const dirs = spec.dataRoots.map((d) => shq(d)).join(" ");
          const out = await exec(
            conn,
            `found=""; for d in ${dirs}; do [ -d "$d" ] && { found="$d"; break; }; done; echo "NXRD:DATA:$found"; ` +
              `mkdir -p ${shq(GAME_BACKUP_DIR)} 2>/dev/null && [ -w ${shq(GAME_BACKUP_DIR)} ] && echo NXRD:BACKUP:ok || echo NXRD:BACKUP:no`,
            QUICK_TIMEOUT_MS
          );
          const data = /NXRD:DATA:(.*)/.exec(out.stdout)?.[1]?.trim() ?? "";
          checks.push({ id: "data_dir", label: "World/save directory present", status: data ? "pass" : "warn", detail: data ? data : `none of ${spec.dataRoots.join(", ")} exists yet` });
          const bk = /NXRD:BACKUP:ok/.test(out.stdout);
          checks.push({ id: "backup_dir", label: "Backup directory writable", status: bk ? "pass" : "warn", detail: bk ? GAME_BACKUP_DIR : `${GAME_BACKUP_DIR} could not be created/written` });
          if (spec.rcon === "source") {
            const rc = await runRcon(conn, spec, spec.listCommand ?? "help").catch((e) => ({ ok: false as const, error: String(e) }));
            checks.push({
              id: "rcon",
              label: "Remote console answers",
              status: rc.ok ? "pass" : "warn",
              detail: rc.ok ? "RCON authenticated and answered" : `RCON did not answer: ${(rc as { error?: string }).error ?? "?"}`,
            });
          }
        });
      } catch (e) {
        checks.push({ id: "data_dir", label: "World/save directory present", status: "warn", detail: `could not check: ${String((e as Error)?.message ?? e).slice(0, 160)}` });
      }
    }

    const ok = !checks.some((c) => c.status === "fail");
    await db.gameRuntime.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, readiness: checks as any, readinessAt: now, readinessOk: ok, intent: "running", intentAt: now, intentSource: "provision" },
      update: { readiness: checks as any, readinessAt: now, readinessOk: ok },
    });
    await db.auditLog
      .create({
        data: {
          userId: null,
          action: ok ? "gameserver.readiness.pass" : "gameserver.readiness.fail",
          detail: `${server.hostname}: ${checks.map((c) => `${c.id}=${c.status}`).join(" ")}`,
        },
      })
      .catch(() => {});
    if (!ok) {
      const failed = checks.filter((c) => c.status === "fail");
      await notifyAdmins(
        `Provision needs attention: ${server.hostname}`,
        `${server.hostname} (${family}) finished provisioning but failed its readiness checklist: ` +
          failed.map((c) => `${c.label} — ${c.detail}`).join("; "),
        `/admin/servers/${server.id}`
      ).catch(() => {});
    }
    return { ok, checks };
  } catch (e) {
    console.error(`[game-runtime] readiness for ${serverId} failed`, e);
    return null;
  }
}

