/** Is the game service running according to one probe? null = could not tell. */
export function serviceRunning(probe: RuntimeProbe | null | undefined): boolean | null {
  if (!probe || !probe.ok) return null;
  const s = probe.service ?? (probe.containerState === "running" ? "active" : probe.containerState ? "inactive" : null);
  if (s === "active" || s === "activating" || s === "reloading") return true;
  if (s === "inactive" || s === "failed" || s === "deactivating") return false;
  return null;
}

/** Did the game process restart between two probes? (its start time moved) */
export function restartedBetween(before: RuntimeProbe | null | undefined, after: RuntimeProbe | null | undefined): boolean {
  const a = before?.startedAt?.getTime();
  const b = after?.startedAt?.getTime();
  return a != null && b != null && b !== a;
}

/** A systemd unit name as reported by the probe, safe to put back into a command. */
export function safeUnitName(unit: string | null | undefined): string | null {
  return unit && /^[A-Za-z0-9_.@-]{1,80}$/.test(unit) ? unit : null;
}
