import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  classifyRuntime,
  controlsFor,
  gameCheckTarget,
  parseRuntimeProbe,
  parseSystemdTime,
  planAfterConfigApply,
  restartedBetween,
  runtimeProbeScript,
  runtimeView,
  safeUnitName,
  serviceRunning,
  sweepDecision,
  intentForPowerAction,
  START_GRACE_MS,
  RUNTIME_STALE_MS,
  type RuntimeProbe,
} from "../lib/game-runtime.ts";
import {
  autoUpdatePlan,
  autoUpdateCopy,
  compareVersions,
  curatedVersionsFor,
} from "../lib/game-update-verify.ts";
import { GAME_FAMILIES } from "../lib/games.ts";
import { controlSpec } from "../lib/game-control.ts";
import { GAME_PORT } from "../lib/games.ts";

/**
 * Game runtime truth — the rules behind the status badge, the power buttons,
 * GAME_CONFIG's run-state reconciliation and the fleet sweep.
 *
 * The incident these hold the line on (2026-09-30, "tomatikk"): the game was
 * stopped, the dashboard said "Online", Start was disabled. Deterministic:
 * no SSH, no DB, a fixed clock.
 */

const NOW = new Date("2026-10-01T05:00:00Z");
const ago = (ms: number) => new Date(NOW.getTime() - ms);

function probe(over: Partial<RuntimeProbe> = {}): RuntimeProbe {
  return {
    ok: true,
    unit: "minecraft",
    service: "active",
    restarts: 0,
    container: "mc",
    containerState: "running",
    containerHealth: "healthy",
    startedAt: ago(60 * 60_000),
    netTable: "",
    netAbsent: false,
    ...over,
  };
}

/* ------------------------------------------------------------------ *
 * The probe script must parse on a customer's server.
 * ------------------------------------------------------------------ */

test("probe script parses under sh -n and dash -n for every family with a control spec", () => {
  for (const fam of GAME_FAMILIES) {
    const spec = controlSpec(fam);
    if (!spec) continue;
    const file = join(tmpdir(), `nxeon-rt-${fam}-${process.pid}.sh`);
    try {
      writeFileSync(file, runtimeProbeScript({ hints: spec.serviceHints, family: fam, protocol: GAME_PORT[fam].protocol }), "utf8");
      execFileSync("sh", ["-n", file]);
      try {
        execFileSync("dash", ["-n", file]);
      } catch (e: any) {
        if (e?.code !== "ENOENT") throw e;
      }
    } finally {
      rmSync(file, { force: true });
    }
  }
});

test("probe script refuses shell-unsafe tokens", () => {
  assert.throws(() => runtimeProbeScript({ hints: ["minecraft"], family: "mc; rm -rf /", protocol: "tcp" }));
  assert.throws(() => runtimeProbeScript({ hints: ["$(id)"], family: "minecraft", protocol: "tcp" }));
});

test("the probe script actually runs and emits its markers on a box with no game", () => {
  // Real shell, real systemctl/docker absence: must still reach END, never throw.
  const out = execFileSync("sh", ["-c", runtimeProbeScript({ hints: ["nxeon-no-such-unit"], family: "minecraft", protocol: "tcp" })]).toString();
  const p = parseRuntimeProbe(out);
  assert.equal(p.ok, true);
  assert.equal(p.container, null);
});

/* ------------------------------------------------------------------ *
 * Parsing
 * ------------------------------------------------------------------ */

test("parseRuntimeProbe reads unit, service, container state, start time and the net table", () => {
  const out = [
    "NXRT:UNIT:minecraft",
    "NXRT:SVC:active",
    "NXRT:NRESTARTS:2",
    "NXRT:SINCE:Thu 2026-10-01 04:23:20 UTC",
    "NXRT:CTR:mc",
