 * ------------------------------------------------------------------ */

test("VM not running → no runtime view (the VM status is the truth)", () => {
  assert.equal(runtimeView({ vmStatus: "STOPPED", row: null, now: NOW }), null);
});

test("no probe yet → 'Checking…' with EVERY control available (never hide Start on a guess)", () => {
  const v = runtimeView({ vmStatus: "RUNNING", row: null, now: NOW })!;
  assert.equal(v.state, "unknown");
  assert.notEqual(v.label, "Online");
  assert.equal(v.canStart, true);
  assert.equal(v.canStop, true);
  assert.equal(v.canRestart, true);
  assert.equal(v.needsRefresh, true);
});

test("game_stopped → Start available, Stop/Restart not; label is not Online", () => {
  const v = runtimeView({ vmStatus: "RUNNING", row: { state: "game_stopped", probedAt: ago(10_000) }, now: NOW })!;
  assert.equal(v.label, "Game stopped");
  assert.equal(v.canStart, true);
  assert.equal(v.canStop, false);
  assert.equal(v.gameUp, false);
  assert.equal(v.needsRefresh, false);
});

test("a stale probe is not trusted to say Online", () => {
  const v = runtimeView({ vmStatus: "RUNNING", row: { state: "online", probedAt: ago(RUNTIME_STALE_MS + 1) }, now: NOW })!;
  assert.equal(v.state, "unknown");
  assert.equal(v.canStart, true);
});

test("legacy _serviceState=inactive with no probe → stopped (never online)", () => {
  const v = runtimeView({ vmStatus: "RUNNING", row: null, now: NOW, legacyServiceState: "inactive" })!;
  assert.equal(v.state, "stopped");
  assert.equal(v.canStart, true);
});

test("legacy _serviceState=active is never enough to claim Online", () => {
  const v = runtimeView({ vmStatus: "RUNNING", row: null, now: NOW, legacyServiceState: "active" })!;
  assert.equal(v.state, "unknown");
});

test("stopped detail names who stopped it", () => {
  const v = runtimeView({
    vmStatus: "RUNNING",
    row: { state: "stopped", probedAt: ago(5000), intent: "stopped", intentSource: "admin", intentAt: ago(60_000) },
    now: NOW,
  })!;
  assert.match(v.detail, /support team/);
});

test("controlsFor: online can't Start; crashed can do everything", () => {
  assert.deepEqual(controlsFor("online"), { canStart: false, canStop: true, canRestart: true });
  assert.deepEqual(controlsFor("crashed"), { canStart: true, canStop: true, canRestart: true });
});

test("intentForPowerAction", () => {
  assert.equal(intentForPowerAction("stop"), "stopped");
  assert.equal(intentForPowerAction("start"), "running");
  assert.equal(intentForPowerAction("restart"), "running");
  assert.equal(intentForPowerAction("nope"), null);
});

/* ------------------------------------------------------------------ *
 * The check target — the GAME_POWER false-failure root cause
 * ------------------------------------------------------------------ */

test("NAT server: check the FORWARDED public port, never node.publicIp:<guest port>", () => {
  const t = gameCheckTarget(
    {
      node: { publicIp: "54.39.132.159" },
      portForwards: [
        { publicPort: 20071, guestPort: 22, protocol: "tcp" },
        { publicPort: 20072, guestPort: 25565, protocol: "tcp" },
      ],
    },
    { port: 25565, protocol: "tcp" }
  );
  assert.deepEqual(t, { host: "54.39.132.159", port: 20072, path: "forward" });
});

test("dedicated IP: the guest port is the public port", () => {
  assert.deepEqual(gameCheckTarget({ dedicatedIp: { address: "1.2.3.4" }, node: { publicIp: "5.6.7.8" } }, { port: 7777, protocol: "udp" }), {
    host: "1.2.3.4",
    port: 7777,
    path: "dedicated",
  });
});

test("no forward for the check port → null (in-guest check only), protocol must match", () => {
  assert.equal(gameCheckTarget({ node: { publicIp: "x" }, portForwards: [] }, { port: 28016, protocol: "tcp" }), null);
  assert.equal(
    gameCheckTarget({ node: { publicIp: "x" }, portForwards: [{ publicPort: 20001, guestPort: 2456, protocol: "udp" }] }, { port: 2456, protocol: "tcp" }),
    null
  );
});

/* ------------------------------------------------------------------ *
 * Fleet sweep
 * ------------------------------------------------------------------ */

const base = { intent: null, downSince: null, alertedAt: null, lastAutoRestartAt: null, autoRestartEnabled: false, now: NOW, alertAfterMs: 10 * 60_000 };

test("sweep: first sight of a down game starts the spell, no alert yet", () => {
  const d = sweepDecision({ ...base, state: "game_stopped" });
  assert.equal(d.downSince?.getTime(), NOW.getTime());
  assert.equal(d.alert, false);
});

test("sweep: down past the threshold → one alert, then no repeat", () => {
  const d1 = sweepDecision({ ...base, state: "crashed", downSince: ago(11 * 60_000) });
  assert.equal(d1.alert, true);
  const d2 = sweepDecision({ ...base, state: "crashed", downSince: ago(30 * 60_000), alertedAt: ago(19 * 60_000) });
  assert.equal(d2.alert, false);
});

test("sweep: an intentional stop is never 'down'", () => {
  const d = sweepDecision({ ...base, state: "stopped", intent: "stopped", downSince: ago(60 * 60_000) });
  assert.equal(d.downSince, null);
  assert.equal(d.alert, false);
  assert.equal(d.autoRestart, false);
});

test("sweep: back online clears the spell and the alert", () => {
  const d = sweepDecision({ ...base, state: "online", downSince: ago(60 * 60_000), alertedAt: ago(40 * 60_000) });
  assert.equal(d.downSince, null);
  assert.equal(d.clearAlert, true);
});

test("sweep: an unknown probe neither starts nor ends a spell", () => {
  const since = ago(5 * 60_000);
  const d = sweepDecision({ ...base, state: "unknown", downSince: since });
  assert.equal(d.downSince, since);
  assert.equal(d.alert, false);
});

test("sweep: auto-restart is OFF unless enabled, and cooled down when it is", () => {
  assert.equal(sweepDecision({ ...base, state: "crashed", downSince: ago(20 * 60_000) }).autoRestart, false);
  assert.equal(sweepDecision({ ...base, state: "crashed", downSince: ago(20 * 60_000), autoRestartEnabled: true }).autoRestart, true);
  assert.equal(
    sweepDecision({ ...base, state: "crashed", downSince: ago(20 * 60_000), autoRestartEnabled: true, lastAutoRestartAt: ago(10 * 60_000) }).autoRestart,
    false
  );
});

/* ------------------------------------------------------------------ *
 * GAME_CONFIG run-state semantics
 * ------------------------------------------------------------------ */

const cfg = { restartedDuringApply: false, restartRequested: false, hasChanges: true, liveApplied: false };

test("config: stopped before → left stopped, and SAID so", () => {
  const p = planAfterConfigApply({ ...cfg, wasRunning: false, isRunning: false });
  assert.equal(p.action, "none");
  assert.match(p.note ?? "", /left it stopped/);
});

test("config: stopped before but the apply recreated (started) it → stop it again", () => {
  assert.equal(planAfterConfigApply({ ...cfg, wasRunning: false, isRunning: true, restartedDuringApply: true }).action, "restore-stop");
});

test("config: stopped + 'Apply & restart' → still left stopped (never start what the owner stopped)", () => {
  const p = planAfterConfigApply({ ...cfg, wasRunning: false, isRunning: false, restartRequested: true });
  assert.equal(p.action, "none");
});

test("config: running before, down after → recover-start (never silently worse)", () => {
  assert.equal(planAfterConfigApply({ ...cfg, wasRunning: true, isRunning: false }).action, "recover-start");
});

test("config: running, file-only change, restart asked → restart; not asked → say a restart is needed", () => {
  assert.equal(planAfterConfigApply({ ...cfg, wasRunning: true, isRunning: true, restartRequested: true }).action, "restart");
  const p = planAfterConfigApply({ ...cfg, wasRunning: true, isRunning: true });
  assert.equal(p.action, "none");
  assert.match(p.note ?? "", /after a restart/);
});

test("config: the apply itself restarted it (container recreate) → nothing more", () => {
  const p = planAfterConfigApply({ ...cfg, wasRunning: true, isRunning: true, restartedDuringApply: true, restartRequested: true });
  assert.equal(p.action, "none");
  assert.equal(p.note, null);
});

test("serviceRunning / restartedBetween / safeUnitName", () => {
  assert.equal(serviceRunning(probe()), true);
  assert.equal(serviceRunning(probe({ service: "inactive" })), false);
  assert.equal(serviceRunning(probe({ ok: false })), null);
  assert.equal(restartedBetween(probe({ startedAt: ago(100) }), probe({ startedAt: ago(10) })), true);
  assert.equal(restartedBetween(probe({ startedAt: ago(100) }), probe({ startedAt: ago(100) })), false);
  assert.equal(safeUnitName("minecraft.service"), "minecraft.service");
  assert.equal(safeUnitName("x'; reboot; '"), null);
});

/* ------------------------------------------------------------------ *
 * Auto-update plan
 * ------------------------------------------------------------------ */

test("compareVersions", () => {
  assert.equal(compareVersions("26.2", "1.21.11"), 1);
  assert.equal(compareVersions("1.21.1", "1.21.10"), -1);
  assert.equal(compareVersions("1.26.45.1", "1.26.45.1"), 0);
});

test("curated lists exist, newest first, no LATEST", () => {
  for (const fam of ["minecraft", "bedrock"]) {
    const list = curatedVersionsFor(fam);
    assert.ok(list.length > 3, fam);
    assert.ok(!list.includes("LATEST"));
    assert.ok(compareVersions(list[0], list[list.length - 1]) > 0, `${fam} not newest-first`);
  }
});

test("autoUpdatePlan: vanilla Minecraft on an old pin → bump to the newest curated version", () => {
  const curated = curatedVersionsFor("minecraft");
  const p = autoUpdatePlan({ family: "minecraft", variant: "vanilla", config: { VERSION: "1.21.1" }, curated });
  assert.equal(p.kind, "bump");
  if (p.kind === "bump") assert.equal(p.to, curated[0]);
});

test("autoUpdatePlan: modded Minecraft never moves its version", () => {
  const p = autoUpdatePlan({ family: "minecraft", variant: "fabric", config: { VERSION: "1.21.1" }, curated: curatedVersionsFor("minecraft") });
  assert.deepEqual(p, { kind: "none", reason: "pinned-for-mods" });
});

test("autoUpdatePlan: LATEST already follows upstream; newest → current; no source → none", () => {
  assert.equal(autoUpdatePlan({ family: "minecraft", variant: "vanilla", config: { VERSION: "LATEST" }, curated: ["26.2"] }).kind, "follows-latest");
  assert.equal(autoUpdatePlan({ family: "minecraft", variant: "vanilla", config: { VERSION: "26.2" }, curated: ["26.2", "26.1"] }).kind, "current");
  assert.equal(autoUpdatePlan({ family: "valheim", variant: "vanilla", config: {}, curated: [] }).kind, "none");
});

test("every family gets honest auto-update copy (no family claims an update source it lacks)", () => {
  for (const fam of GAME_FAMILIES) {
    const plan = autoUpdatePlan({ family: fam, variant: null, config: { VERSION: "1.0" }, curated: curatedVersionsFor(fam) });
    const copy = autoUpdateCopy(plan, fam);
    assert.ok(copy.length > 40, fam);
    if (plan.kind === "none") assert.match(copy, /nothing is downloaded and nothing restarts/, fam);
  }
});

