"use client";

import { useState, useTransition } from "react";
import { serverAction } from "@/lib/actions";

/**
 * Admin Start/Stop/Reboot on the server detail page.
 *
 * Deliberately LIGHTER than the customer controls (components/customer/power/
 * usePowerGuard.ts): staff are not the people confused by a slow action, every
 * click already goes through a window.confirm (itself a hard stop on reflexive
 * double-clicks), and the backend refusal message is shown verbatim. What it
 * does share: the buttons stay disabled for as long as the server has ANY job
 * in flight, with the job named — previously they re-enabled the moment the
 * request returned, so the only thing between an operator and a duplicate
 * START was the backend guard (which had its own race until 2026-09-30, see
 * lib/job-guard.ts). No post-completion cooldown: a quick follow-up action is
 * a legitimate staff need. The page's own <AutoRefresh/> keeps `activeJob` live.
 */
export function PowerActions({
  serverId,
  status,
  activeJob = null,
}: {
  serverId: string;
  status: string;
  /** The server's QUEUED/RUNNING job, if any (the page's `server.jobs`). */
  activeJob?: { type: string; status: string } | null;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const run = (action: "start" | "stop" | "reboot") => {
    if (window.confirm(`Send ${action.toUpperCase()} to this server?`)) {
      setError(null);
      // serverAction returns { error } now — an operator sees why a click did
      // nothing instead of silence.
      start(async () => {
        const res = await serverAction(serverId, action);
        if (res?.error) setError(res.error);
      });

};

export function areaForHref(href: string): Area {
  return HREF_AREA[href] ?? "platform";
}

export function canAccessHref(role: Role, href: string): boolean {
  return canAccess(role, areaForHref(href));
}

/**
 * Server-side page guard. Redirects to /login if signed out, or back to the
 * overview if the (staff) user's role can't reach this area. Returns the real
 * signed-in user (impersonation is refused elsewhere in the admin layout).
 */
export async function requireArea(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  if (!canAccess(user.role, area)) redirect("/admin");
  return user;
}
