"use server";

/**
 * Admin controls for game runtime truth (components/admin/GameRuntimeCard.tsx):
 * probe now, game-service power, auto-restart opt-in, and the auto-update
 * override. Every action is `requireArea("fleet")`-gated, audit-logged, and
 * — for anything that changes a server — goes through a Job (the web app
 * never touches the guest except for the read-only probe).
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { withServerJobLock } from "./job-guard";
import { isPowerAction } from "./game-control";
import { refreshRuntime, familyOf } from "./game-runtime-probe";

type R = { ok: true } | { ok: false; error: string };

async function gameServer(serverId: string) {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, hostname: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } },
  });
  if (!server || !familyOf(server)) throw new Error("Not a game server.");
  return server;
}

export async function adminProbeGameRuntime(serverId: string): Promise<R> {
  const admin = await requireArea("fleet");
  try {
    const server = await gameServer(serverId);
    const r = await refreshRuntime(server.id);
    await db.auditLog.create({
      data: { userId: admin.id, action: "admin.gameserver.runtime_probe", detail: `${server.hostname} → ${r?.state ?? "n/a"}` },
    });
    revalidatePath(`/admin/servers/${serverId}`);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: (e as Error).message.slice(0, 200) };
  }
}

export async function adminGamePower(serverId: string, action: string): Promise<R> {
  const admin = await requireArea("fleet");
  if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
  try {
    const server = await gameServer(serverId);
    if (server.status !== "RUNNING") return { ok: false, error: "The VM must be running to control the game service." };
    const res = await withServerJobLock(server.id, async (tx) => {
      const busy = await tx.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
      if (busy > 0) return { busy: true } as const;
      await tx.job.create({
        data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: action === "restart", source: "admin", by: admin.id } },
      });
      return { busy: false } as const;
    });
    if (res.busy) return { ok: false, error: "Another job is in flight on this server." };
    await db.auditLog.create({ data: { userId: admin.id, action: "admin.gameserver.power", detail: `${action} on ${server.hostname}` } });
    revalidatePath(`/admin/servers/${serverId}`);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: (e as Error).message.slice(0, 200) };
  }
}

/** Per-server auto-restart (default OFF). The global GAME_AUTO_RESTART=1 env also enables it fleet-wide. */
export async function adminSetGameAutoRestart(serverId: string, enabled: boolean): Promise<R> {
  const admin = await requireArea("fleet");
  try {
    const server = await gameServer(serverId);
    await db.gameRuntime.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, autoRestart: enabled },
      update: { autoRestart: enabled },
    });
    await db.auditLog.create({
      data: { userId: admin.id, action: "admin.gameserver.auto_restart", detail: `${server.hostname} → ${enabled ? "on" : "off"}` },
    });
    revalidatePath(`/admin/servers/${serverId}`);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: (e as Error).message.slice(0, 200) };
  }
}

/** Admin override for automatic updates: set the flag, and optionally lock it against customer changes. */
export async function adminSetGameAutoUpdate(serverId: string, enabled: boolean, locked: boolean): Promise<R> {
  const admin = await requireArea("fleet");
  try {
    const server = await gameServer(serverId);
    await db.server.update({ where: { id: server.id }, data: { autoUpdate: enabled } });
    await db.gameRuntime.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, autoUpdateLocked: locked },
      update: { autoUpdateLocked: locked },
    });
    await db.auditLog.create({
      data: {
        userId: admin.id,
        action: "admin.gameserver.auto_update",
        detail: `${server.hostname} → ${enabled ? "on" : "off"}${locked ? " (locked)" : ""}`,
      },
    });
    revalidatePath(`/admin/servers/${serverId}`);
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: (e as Error).message.slice(0, 200) };
  }
}

