const TONE = { ok: "green", info: "brand", warn: "amber", bad: "red", muted: "slate" } as const;
const CHECK_TONE = { pass: "green", fail: "red", warn: "amber", skip: "slate" } as const;

function yn(v: boolean | null): string {
  return v === true ? "yes" : v === false ? "no" : "—";
}

/**
 * Admin view of the GAME inside a game server (lib/game-runtime.ts): the
