              ["Port bound in guest", yn(row?.portBound ?? null)],
              ["Public path answers", `${yn(row?.externalOk ?? null)}${row?.externalTarget ? ` (${row.externalTarget})` : ""}`],
              ["State since", row?.stateSince ? timeAgo(row.stateSince) : "—"],
              ["Run intent", row?.intent ? `${row.intent} by ${row.intentSource ?? "?"}${row.intentAt ? `, ${timeAgo(row.intentAt)}` : ""}` : "none recorded"],
              ["Down (unexplained) since", row?.downSince ? timeAgo(row.downSince) : "—"],
