                <dd className="max-w-[60%] text-right font-mono text-[11px] text-slate-300">{v}</dd>
              </div>
            ))}
          </dl>
          {view && <p className="mt-3 text-xs text-slate-400">{view.detail}</p>}
        </div>
        <div className="space-y-5">
          <GameRuntimeControls
            serverId={serverId}
            canStart={vmStatus === "RUNNING" && (view?.canStart ?? true)}
            canStop={vmStatus === "RUNNING" && (view?.canStop ?? true)}
            canRestart={vmStatus === "RUNNING" && (view?.canRestart ?? true)}
            autoRestart={!!row?.autoRestart}
            autoUpdate={autoUpdate}
            autoUpdateLocked={!!row?.autoUpdateLocked}
            busy={busy}
          />
          <div>
            <h3 className="mb-2 flex items-center gap-2 text-sm font-semibold">
              Provision readiness
              {row?.readinessOk === true && <Badge tone="green">passed</Badge>}
              {row?.readinessOk === false && <Badge tone="red">needs attention</Badge>}
            </h3>
            {checks.length === 0 ? (
              <p className="text-xs text-slate-500">No readiness checklist recorded (provisioned before 2026-10-01, or not a fresh provision).</p>
            ) : (
              <ul className="space-y-1.5 text-xs">
                {checks.map((c) => (
                  <li key={c.id} className="flex items-start justify-between gap-3">
                    <span>
                      <span className="text-slate-200">{c.label}</span>
                      <span className="block text-[11px] text-slate-500">{c.detail}</span>
                    </span>
                    <Badge tone={CHECK_TONE[c.status] ?? "slate"}>{c.status}</Badge>
                  </li>
                ))}
              </ul>
            )}
            {row?.readinessAt && <p className="mt-2 text-[11px] text-slate-600">Recorded {timeAgo(row.readinessAt)}</p>}
          </div>
        </div>
      </div>
    </div>
  );
}
