const TONE = { ok: "green", info: "brand", warn: "amber", bad: "red", muted: "slate" } as const;

/**
 * Fleet view of game runtime truth: every running game server's real game
 * state (worker/game-runtime.ts sweep, ~2 min), its run intent, unexplained
 * down spells and failed readiness checklists — worst first.
 */
export default async function GameHealthPage() {
  await requireArea("fleet");
  const servers = await db.server.findMany({
    where: {
      status: { in: ["RUNNING", "STOPPED", "ERROR"] },
      OR: [{ gamePlanId: { not: null } }, { osTemplate: { family: { in: [...GAME_FAMILIES] } } }],
    },
    select: {
      id: true,
      hostname: true,
      status: true,
      gameConfig: true,
      autoUpdate: true,
