                    <div className="text-[11px] text-slate-500">{s.user?.email}</div>
                  </td>
                  <td className="text-xs">{s.gamePlan?.gameFamily ?? s.osTemplate.family}</td>
                  <td className="text-xs">{s.node?.name ?? "—"}</td>
