                  <td className="text-xs">{s.gameRuntime?.intent ? `${s.gameRuntime.intent} (${s.gameRuntime.intentSource ?? "?"})` : "—"}</td>
                  <td className="text-xs">{down && s.gameRuntime?.downSince ? <span className="text-red-300">{timeAgo(s.gameRuntime.downSince)}</span> : "—"}</td>
