/**
 * Run the post-provision readiness checklist (worker/game-runtime.ts
 * runProvisionReadiness) for game servers that were provisioned before it
 * existed, so /admin/game-health and the admin server page have a checklist
 * for the whole fleet, not just new orders.
 *
 * What it touches on each guest: read-only probes, plus `mkdir -p
 * /var/backups/nxeon-game` (the backup dir check) — the same directory
 * "Back up now" creates. It never starts/stops/restarts anything. It writes
 * GameRuntime rows + AuditLog, and alerts admins for failures.
 *
 * Usage (on the primary, from /opt/nxeon, AFTER this branch is deployed):
 *   npx tsx scripts/game-readiness-run.ts <serverId>      # one server
 *   npx tsx scripts/game-readiness-run.ts --all           # every RUNNING game server
 * Default with no args prints usage and does nothing.
 */
import { db } from "../lib/db";
import { GAME_FAMILIES } from "../lib/games";
import { runProvisionReadiness } from "../worker/game-runtime";

async function main() {
  const arg = process.argv[2];
  if (!arg) {
    console.log("usage: npx tsx scripts/game-readiness-run.ts <serverId> | --all");
    return;
  }
  const ids =
    arg === "--all"
      ? (
          await db.server.findMany({
            where: { status: "RUNNING", OR: [{ gamePlanId: { not: null } }, { osTemplate: { family: { in: [...GAME_FAMILIES] } } }] },
            select: { id: true },
          })
        ).map((s) => s.id)
      : [arg];
  for (const id of ids) {
    const r = await runProvisionReadiness(id);
    const s = await db.server.findUnique({ where: { id }, select: { hostname: true } });
    console.log(
      `${s?.hostname ?? id}: ${r ? (r.ok ? "PASS" : "NEEDS ATTENTION") : "skipped"}` +
        (r ? `  ${r.checks.map((c) => `${c.id}=${c.status}`).join(" ")}` : "")
    );
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

